'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('olive','Olive comes through Old French and Latin from Greek elaia; it names the fruit, the tree, and a muted yellow-green color.',[C('olive.s1','橄榄果','The cook sliced green olives into the salad just before serving it with warm bread.','厨师在上桌前把青橄榄切片放进沙拉里，并配上热面包。','The cook sliced green olives / into the salad / just before serving it with warm bread.','olive 可指可食用的椭圆形果实，也可榨油。','例句中的食材是切片加入沙拉的橄榄果。'),C('olive.s2','橄榄树','An old olive grows beside the farmhouse, and its branches still produce fruit every autumn.','农舍旁长着一棵老橄榄树，每年秋天枝头仍会结果。','An old olive grows beside the farmhouse / and its branches / still produce fruit every autumn.','olive 也可指结出橄榄果的树。','树枝每年结果，说明此处指植物。'),C('olive.s3','橄榄色','She chose an olive jacket whose muted yellow-green shade matched the hiking bag.','她选了一件橄榄色外套，柔和的黄绿色与登山包很相配。','She chose an olive jacket / whose muted yellow-green shade / matched the hiking bag.','olive 可作颜色形容词，表示暗黄绿色。','颜色义由 muted yellow-green shade 明确说明。')],M('The farmer harvested ripe olives from the olive tree, then described the fruit as a yellow-green color.','The farmer harvested ripe olives from the olive tree, then described the jacket as olive.','句中 fruit 指果实，olive 作颜色形容词应修饰 jacket 等物品。','word-choice'),[q('What did the cook add to the salad?','sliced green fruit','an olive-colored jacket','a branch from the farmhouse','厨师切入沙拉的是橄榄果。'),q('Which olive still produced fruit each autumn?','the tree beside the farmhouse','the hiking bag','the salad bowl','每年结果的 olive 指橄榄树。',2,'context'),q('What color was the jacket?','muted yellow-green','bright red','deep blue','例句把 olive 描述为柔和的黄绿色。',3,'meaning'),q('Which sentence uses olive as a color adjective?','He wore an olive coat.','He pressed olives for oil.','An olive grew beside the house.','olive 修饰 coat，表示颜色。',3,'grammar')]);
P('oliver','Oliver is a specialized English metalworking term for a foot-operated smith’s hammer; its historical naming is uncertain in the available source.',C('oliver.s1','脚踏铁锤','The blacksmith pressed the treadle, and the oliver dropped its heavy head to shape the glowing bar.','铁匠踩下踏板，脚踏锤的重锤头落下，把烧红的铁条锻成形。','The blacksmith pressed the treadle / and the oliver dropped its heavy head / to shape the glowing bar.','oliver 是由脚踏控制、靠重锤落下工作的锻造工具。','踩踏板使锤头落下敲打金属。'),M('The smith used the oliver by lifting its hammer head with one hand and never operating the foot treadle.','The smith operated the oliver by pressing its foot treadle so the hammer head could fall.','该工具由脚踏板控制，手动提起锤头不是例句中的操作方式。','meaning'),[q('What did the oliver shape?','a glowing metal bar','a green olive fruit','a hiking bag','脚踏锤用于锻打烧红的铁条。'),q('How did the smith operate the tool?','by pressing a treadle with a foot','by turning a color wheel','by slicing fruit into a salad','脚踏板控制 oliver 的锤头动作。',1,'context'),q('Which tool matches the source definition of oliver?','a smith’s hammer lifted by foot and falling by its own weight','a hand saw used to cut olive branches','a device that measures the color green','oliver 是脚踏铁锤，不是锯子或颜色测量器。',1,'meaning'),q('What should be said about the word’s historical name?','its origin is uncertain in the available source','it is certainly the Latin word for olive','it was formed from Olympic and hammer','现有来源没有可靠解释该专门术语的命名史。',1,'word-formation')]);
P('Olympic','Olympic comes from Greek Olympia, the site of the ancient games; it can describe the international games or refer to the Games themselves.',[C('Olympic.s1','奥运会的','The Olympic swimming trials drew athletes who had trained for years to qualify for the international competition.','奥运会游泳选拔赛吸引了训练多年、希望获得国际赛事资格的运动员。','The Olympic swimming trials drew athletes / who had trained for years / to qualify for the international competition.','Olympic 作形容词表示与奥林匹克运动会有关。','选拔赛是为国际奥运赛事挑选运动员。'),C('Olympic.s2','奥运会','The Olympics begin next week, and the opening ceremony will be broadcast worldwide.','奥运会下周开幕，开幕式将在全球播出。','The Olympics begin next week / and the opening ceremony / will be broadcast worldwide.','the Olympics 常以复数形式指奥林匹克运动会本身。','开幕式标明这里指整个赛事。')],M('The Olympic Games began next week and the opening ceremony was broadcast last year.','The Olympic Games begin next week, and the opening ceremony will be broadcast then.','时间线应一致；下周开始的赛事不能同时说开幕式去年播出。','grammar'),[q('What did the swimmers hope to achieve?','qualify for the international games','win a local cooking contest','train for the opening ceremony broadcast only','运动员参加选拔，希望取得国际赛事资格。'),q('What begins next week in the second context?','the Olympic Games','the swimming pool’s renovation','a city marathon','the Olympics 指奥林匹克运动会。',2,'context'),q('Which phrase uses Olympic as an adjective?','Olympic trials','the Olympics','an olive tree','Olympic 修饰 trials，描述赛事类别。',1,'grammar'),q('Which event belongs to the Olympics sense?','the international Games themselves','a private swimming lesson','a fruit harvest','第二个义项指奥林匹克运动会本身。',2,'meaning')]);
P('omelet','Omelet came into English through French omelette and names beaten eggs cooked in a pan, often folded around a filling.',C('omelet.s1','摊鸡蛋；蛋卷','For breakfast, Ravi made an omelet with spinach and cheese and folded it over before serving.','早餐时，拉维用菠菜和奶酪做了蛋卷，上桌前把它对折起来。','For breakfast / Ravi made an omelet with spinach and cheese / and folded it over before serving.','omelet 指在锅中煎熟、常包入馅料并折叠的鸡蛋料理。','菠菜和奶酪是馅料，成品被折起。'),M('Ravi made an omelet by serving raw beaten eggs in a glass without cooking them.','Ravi made an omelet by cooking beaten eggs in a pan and folding them around the filling.','omelet 是煎熟的鸡蛋料理，不是未烹煮的生蛋液。','meaning'),[q('What was folded into Ravi’s omelet?','spinach and cheese','a Roman numeral','a blacksmith’s hammer','蛋卷里包了菠菜和奶酪。'),q('How is an omelet normally prepared?','beaten eggs are cooked in a pan','whole eggs are frozen inside a loaf','raw eggs are poured into a glass','omelet 由打散的鸡蛋在锅中煎熟。',1,'meaning'),q('When did Ravi fold the omelet?','before serving it','before the eggs were beaten','after the pan was washed','上桌之前他把蛋卷折起。',1,'context'),q('Which word is the French loan behind omelet?','omelette','Olympia','omnibus','英语 omelet 来自法语 omelette。',1,'word-formation')]);
P('omen','Omen comes from Latin omen, “sign or forewarning”; it can be an event taken as a sign of the future or a verb meaning to foretell.',[C('omen.s1','征兆','The sudden ring of the old bell was taken as an omen by villagers who expected a storm that night.','村民预料当晚有暴风雨，于是把老钟突然响起视为一种征兆。','The sudden ring of the old bell / was taken as an omen / by villagers who expected a storm that night.','omen 作名词可指被认为预示未来的事件或迹象。','村民把钟声与即将到来的风暴联系起来。'),C('omen.s2','预示','The dark clouds omen a difficult crossing for the fishing boats returning to shore.','乌云预示着返岸的渔船将面临艰难航程。','The dark clouds omen a difficult crossing / for the fishing boats / returning to shore.','omen 也可作动词，表示预示未来事件。','云层被用作未来航程艰难的迹象。')],M('The dark clouds were an omen of clear skies, and the boats faced no bad weather at all.','The dark clouds were an omen of rough weather for the returning boats.','乌云不能在该语境中预示完全晴朗，前后含义冲突。','meaning'),[q('What did villagers take as an omen?','the old bell’s sudden ring','a cooked omelet','an Olympic medal','村民把老钟突然响起看成征兆。'),q('What do the dark clouds omen?','a difficult crossing for the boats','a successful harvest of olives','a quiet indoor concert','作动词时，omen 表示预示艰难航程。',2,'context'),q('Which use makes omen a noun?','They regarded the strange light as an omen.','Clouds omen a storm.','The clouds are omening the boats.','第一句中 omen 是“征兆”名词。',1,'grammar'),q('In the second example, omen means?','to indicate a future event','to fold eggs in a pan','to describe a color','动词 omen 表示预示未来。',2,'meaning')]);
P('ominous','Ominous is formed from omen plus -ous and describes something that suggests a bad event may happen.',C('ominous.s1','不祥的','An ominous silence fell over the control room when the warning lights began flashing red.','警示灯开始闪红时，控制室里笼罩着一种不祥的沉默。','An ominous silence fell over the control room / when the warning lights / began flashing red.','ominous 修饰 silence，表示让人觉得坏事将要发生。','红色警示灯和沉默营造出危险将至的感觉。'),M('The dark warning siren sounded ominous because everyone knew it guaranteed a safe and uneventful night.','The dark warning siren sounded ominous because it suggested danger might be near.','预示安全平静的声音不符合 ominous 的不祥含义。','meaning'),[q('What created an ominous feeling in the control room?','red warning lights and sudden silence','a breakfast omelet','a list of Olympic swimmers','红灯闪烁时出现的沉默令人觉得不祥。'),q('Which scene is ominous?','a warning siren sounds as dark clouds gather','a clear sky follows a successful rescue','a quiet room is filled with warm sunlight','ominous 暗示可能有坏事发生。',1,'meaning'),q('What began flashing red?','the warning lights','the old bell','the river crossing','控制室里的警示灯开始闪红。',1,'context'),q('Which suffix helps form ominous from omen?','-ous','-er','-less','ominous 由 omen 加 -ous 构成形容词。',1,'word-formation')]);
P('omission','Omission comes from Latin omissionem, from omittere, “to leave out”; it means something left out or the act of leaving it out.',C('omission.s1','遗漏；省略','The editor corrected an omission in the safety checklist: the final step had been left out of the printed copy.','编辑修正了安全清单中的一处遗漏：最后一步没有印在副本里。','The editor corrected an omission / in the safety checklist / the final step had been left out of the printed copy.','omission 可指被漏掉的内容或省略这一行为。','清单里缺少最后一步。'),M('The checklist contained an omission even though every required step appeared once and in the correct order.','The checklist contained an omission because the required final step was missing.','如果每一步都完整出现，就不存在这里所说的遗漏。','meaning'),[q('What was missing from the printed checklist?','the final step','the title of an omelet recipe','a list of Olympic athletes','清单漏掉了最后一步。'),q('Which situation is an omission?','a required safety warning is accidentally left out','every instruction is included once','a warning is repeated clearly','遗漏就是应有内容被漏掉。',1,'meaning'),q('Who corrected the checklist?','the editor','the blacksmith','a swimmer','编辑发现并修正了遗漏。',1,'context'),q('Which Latin verb is omission related to?','omittere, “to leave out”','nutrire, “to feed”','numerare, “to count”','omission 与表示“省去”的 omittere 有关。',1,'word-formation')]);
P('omit','Omit comes from Latin omittere, “to let go or leave out”; it means deliberately leaving out material or failing to include something required.',[C('omit.s1','有意省略','The speaker omitted the final anecdote to keep the presentation within its allotted time.','为了让演讲不超时，发言者有意省略了最后一个轶事。','The speaker omitted the final anecdote / to keep the presentation / within its allotted time.','omit 可表示有意从文字或讲话中删去某部分。','删去轶事是为了控制时长。'),C('omit.s2','遗漏；未做','The report omitted the laboratory’s address, so readers could not find where the samples had been tested.','报告漏掉了实验室地址，因此读者无法得知样本的检测地点。','The report omitted the laboratory’s address / so readers could not find / where the samples had been tested.','omit 也可指未能包含应有内容或未做应做的事。','地址缺失造成信息不完整。')],M('The report omitted the address and then printed it clearly in the first paragraph.','The report omitted the address, leaving readers without the laboratory’s location.','若地址已清楚印出，就不能说报告漏掉了它。','meaning'),[q('Why did the speaker omit the anecdote?','to stay within the time limit','to add another twenty minutes','to explain the laboratory address','省略轶事是为了不超时。'),q('What information did the report omit?','the laboratory’s address','the presentation’s final anecdote','the Olympic opening date','报告漏掉了实验室地址。',2,'context'),q('Which use means intentionally leave material out?','She omitted the last paragraph to shorten the article.','The report omitted the address by mistake.','He added every missing page.','第一句明确表示有意缩短文章。',1,'meaning'),q('Which use means fail to include required information?','The form omitted the applicant’s signature line.','The writer chose to omit one optional story.','The audience omitted the encore by leaving early.','表格缺少必需签名栏，属于遗漏。',2,'meaning')]);
P('omnibus','Omnibus comes from Latin omnibus, “for all”; it can mean a collection of several works, formerly a public bus, or something comprehensive.',[C('omnibus.s1','选集；公共汽车','The library bought an omnibus containing three early detective novels by the same author.','图书馆买了一本选集，收录了同一作者早期的三部侦探小说。','The library bought an omnibus / containing three early detective novels / by the same author.','omnibus 可指汇集多部作品的选集，也曾用作公共汽车的名称。','一本书收录了三部作品。'),C('omnibus.s2','综合性的','The committee approved an omnibus bill that combined housing, transit, and school funding measures.','委员会通过了一项综合法案，把住房、交通和学校拨款措施合并在一起。','The committee approved an omnibus bill / that combined housing, transit, and school funding measures.','omnibus 作形容词可表示汇集多个主题或措施的综合性文件。','一项法案合并了多个政策领域。')],M('The library’s omnibus contained only one short story, so it was a collection of three novels by the same author.','The library’s omnibus contained three novels by the same author.','若只收一篇故事，就不符合此处“收录多部作品”的描述。','meaning'),[q('What did the library’s omnibus contain?','three detective novels','three bus tickets','a single school funding measure','选集里收录三部侦探小说。'),q('What did the omnibus bill combine?','housing, transit, and school funding measures','only a single bus route','three novels by one writer','综合法案合并了住房、交通和学校拨款措施。',2,'context'),q('Which is an omnibus in the book sense?','a volume collecting several works','a blank notebook with no pages','a single unsigned letter','书籍义的 omnibus 是收录多部作品的选集。',1,'meaning'),q('What does the Latin source omnibus mean?','for all','not at all','to leave out','omnibus 源自拉丁语“给所有人；为所有人”。',1,'word-formation')]);
P('omnipotence','Omnipotence combines Latin omni-, “all,” with potentia, “power,” and means the quality of being able to do anything.',C('omnipotence.s1','全能；无限权力','The novel questions the king’s omnipotence by showing that even his strongest orders cannot stop a drought.','小说通过展现国王最强硬的命令也无法阻止干旱，质疑了他的无限权力。','The novel questions the king’s omnipotence / by showing / that even his strongest orders cannot stop a drought.','omnipotence 是名词，指能够做任何事的全能或无限权力。','自然干旱说明国王的权力并非真正无限。'),M('The story proved the king’s omnipotence because he could not influence any event or make any decision.','The story questioned the king’s omnipotence because his power could not stop the drought.','无法影响事情或作出决定不能证明一个人全能。','meaning'),[q('What limited the king’s power in the story?','a drought his orders could not stop','a public bus full of passengers','an omitted anecdote','干旱无法被国王命令阻止。'),q('What does omnipotence mean?','the quality of being able to do anything','the act of leaving out a paragraph','the quality of eating plants and meat','omnipotence 指全能或无限权力。',1,'meaning'),q('What did the novel question?','whether the king’s power was truly unlimited','whether the bus had enough seats','whether the drought was a color','小说质疑国王是否真正拥有无限权力。',1,'context'),q('Which word part means “all” in omnipotence?','omni-','-ence','potentia','omni- 表示“全部、全”。',1,'word-formation')]);
P('omnipotent','Omnipotent combines omni-, “all,” with potent, “powerful,” and describes someone or something with unlimited power.',C('omnipotent.s1','全能的','In the myth, the omnipotent creator could form mountains, rivers, and living things with a single command.','神话中，全能的造物者只需一道命令就能创造山川河流和生灵。','In the myth / the omnipotent creator could form mountains, rivers, and living things / with a single command.','omnipotent 作形容词，表示拥有无限力量。','一道命令便能创造各种事物体现全能。'),M('The omnipotent ruler had no power to make a single change and could not carry out any command.','The omnipotent ruler was described as having unlimited power to carry out commands.','完全没有能力与 omnipotent 的“全能”相反。','meaning'),[q('What could the omnipotent creator make?','mountains, rivers, and living things','only one written notice','a single missing paragraph','神话中的造物者能创造山川、河流和生灵。'),q('Which being is omnipotent in the myth?','the creator with unlimited power','a novice who is still learning','a bus driver with one route','omnipotent 描述拥有无限力量的造物者。',1,'meaning'),q('How many commands were needed to create the world’s features?','one','three hundred','none were allowed','神话说一道命令就能创造这些事物。',1,'context'),q('What does omni- contribute to omnipotent?','the meaning “all”','the meaning “small”','the meaning “food”','omni- 表示“全、所有”。',1,'word-formation')]);
P('omnivore','Omnivore combines Latin omnis, “all,” with vorare, “to devour”; it names an animal whose diet includes both plant and animal food.',C('omnivore.s1','杂食动物','A bear is an omnivore: it may eat berries in summer and fish when it can catch them.','熊是杂食动物：夏天可能吃浆果，也会在捕到鱼时吃鱼。','A bear is an omnivore / it may eat berries in summer / and fish when it can catch them.','omnivore 指饮食中既包括植物性食物也包括动物性食物的动物。','浆果和鱼分别代表植物性与动物性食物。'),M('The bear was an omnivore because it ate only berries and never consumed any animal food.','The bear was an omnivore because it ate both berries and fish.','只吃植物性食物不符合“兼吃植物和动物”的定义。','meaning'),[q('What two kinds of food might the bear eat?','berries and fish','only leaves and grass','only insects and fish','浆果是植物性食物，鱼是动物性食物。'),q('Which animal is an omnivore?','one that eats both plant and animal foods','one that eats only leaves','one that eats only meat','omnivore 的饮食包含植物和动物食物。',1,'meaning'),q('When might the bear eat fish?','when it can catch them','only when it is a plant','after an Olympic race','例句说熊会在捕到鱼时吃鱼。',1,'context'),q('What does the Latin element vorare mean?','to devour','to leave out','to mark a number','vorare 表示“吞食”。',1,'word-formation')]);
P('omnivorous','Omnivorous is formed from omnivore and -ous; it describes an animal that eats plants and meat, or someone eager to take in many things of one kind.',[C('omnivorous.s1','杂食的','The omnivorous raccoon ate fallen fruit from the orchard and insects from beneath the log.','这只杂食浣熊吃果园里掉落的水果，也吃木头下面的昆虫。','The omnivorous raccoon ate fallen fruit / from the orchard / and insects from beneath the log.','omnivorous 作形容词表示既吃植物也吃动物性食物。','水果和昆虫代表两类食物。'),C('omnivorous.s2','什么都读或吸收的','An omnivorous reader, Salma moved from history to science fiction and then to biographies each month.','萨尔玛是个什么书都读的读者，每个月会从历史读到科幻，再读传记。','An omnivorous reader / Salma moved from history to science fiction / and then to biographies each month.','omnivorous 也可比喻形容广泛涉猎某一类事物。','她阅读题材广泛，涉及多种类型。')],M('The omnivorous raccoon ate only one kind of leaf and refused every fruit or insect.','The omnivorous raccoon ate both fruit and insects.','只吃一种叶子不符合既摄取植物又摄取动物性食物的含义。','meaning'),[q('What did the raccoon eat from the orchard?','fallen fruit','biographies','a metal hammer','浣熊吃了果园里掉落的水果。'),q('What kind of reader is Salma?','one who reads widely across genres','one who reads only a single history book','one who avoids all printed material','omnivorous reader 指广泛阅读各种题材的人。',2,'context'),q('Which description is omnivorous in the literal sense?','an animal eating fruit and insects','an animal eating only grass','a reader choosing books from several genres','果实和昆虫都是动物饮食中的不同类别。',1,'meaning'),q('Which suffix appears in omnivorous?','-ous','-ment','-er','omnivorous 由 omnivore 加 -ous 构成。',1,'word-formation')]);
P('on','On comes from Old English on; it can indicate surface contact, a day or occasion, a subject, an operating or scheduled state, or continuation.',[C('on.s1','在……上面','The olive bowl sat on the wooden table beside the open window.','橄榄碗放在敞开的窗户旁边的木桌上。','The olive bowl sat on the wooden table / beside the open window.','on 可表示物体接触并由某表面支撑。','碗放在桌面上并受到支撑。'),C('on.s2','在某日或场合','The museum’s evening lecture is on Thursday, and visitors must book a seat in advance.','博物馆的晚间讲座安排在星期四，访客须提前订座。','The museum’s evening lecture is on Thursday / and visitors must book a seat / in advance.','on 可用于具体日期或某个场合。','Thursday 是讲座举行的具体日期。'),C('on.s3','关于','The class watched a short film on ancient Olympic training methods.','班级观看了一部关于古代奥林匹克训练方法的短片。','The class watched a short film / on ancient Olympic training methods.','on 可引出书籍、讲话或影片所讨论的主题。','影片主题是古代训练方法。'),C('on.s4','开着；进行中','The radio is on, so the crew can hear the harbor weather report.','收音机开着，因此船员能听到港口天气预报。','The radio is on / so the crew can hear / the harbor weather report.','on 可描述设备正在运行，或活动正在进行、节目正在上演。','收音机开着才能接收播报。'),C('on.s5','继续；向前','After a short rest, the hikers walked on toward the ridge before sunset.','短暂休息后，徒步者继续向山脊走去，赶在日落之前到达。','After a short rest / the hikers walked on / toward the ridge before sunset.','on 可作副词，表示继续或朝同一方向前进。','休息后他们继续向前走。')],M('The radio was on, but it was switched off and could not receive the weather report.','The radio was on, so it could receive the weather report.','设备若已关闭就不能称为开着。','meaning'),[q('Where was the olive bowl?','on the wooden table','under the table','inside the radio','碗与桌面接触并由桌面支撑。'),q('When is the museum lecture?','on Thursday','in the wooden table','toward the ridge','on 可与具体星期日期连用。',2,'context'),q('What is the short film about?','ancient Olympic training methods','the olive harvest only','the harbor radio’s volume','on 在此引出影片主题。',3,'meaning'),q('What happened after the hikers rested?','they continued toward the ridge','they turned the radio off','they booked a lecture seat','walked on 表示继续向前走。',5,'meaning')]);
P('on condition','On condition is a fixed phrase meaning only if a particular requirement is met; it often appears as on condition that.',C('on condition.s1','条件是；如果','The archive allowed the researcher to photograph the letters on condition that no flash was used.','档案馆允许研究人员拍摄信件，条件是不使用闪光灯。','The archive allowed the researcher to photograph the letters / on condition that no flash was used.','on condition that 引出允许某事发生的具体条件。','拍摄被允许，但不能使用闪光灯。'),M('The archive allowed flash photography on condition that the researcher did not use a flash.','The archive allowed photography on condition that the researcher did not use a flash.','允许闪光摄影与条件中“不使用闪光灯”相矛盾。','meaning'),[q('What condition did the archive set?','the researcher must not use a flash','the researcher must photograph every letter twice','the researcher must publish the letters online','拍摄条件是不得使用闪光灯。'),q('Which sentence uses on condition that correctly?','You may borrow the key on condition that you return it tonight.','You may borrow the key on condition returning it tonight.','You may borrow the key on condition you returned it yesterday.','on condition that 后接完整从句，说明借钥匙的条件。',1,'grammar'),q('What did the archive permit?','photographing the letters without flash','posting the letters on the internet','removing the letters from the building','档案馆允许拍摄，但要求不开闪光灯。',1,'context'),q('On condition is closest to?','only if','even though','as a result','该短语表示“只有在……条件下”。',1,'meaning')]);
P('on earth','On earth is an emphatic phrase used after words such as what, why, or how to express surprise, frustration, or strong curiosity.',C('on earth.s1','究竟；到底','“Why on earth did the warning system stay silent?” the harbor manager asked after the storm passed.','风暴过去后，港口经理问：“警报系统究竟为什么一直没有响？”','“Why on earth did the warning system stay silent?” / the harbor manager asked / after the storm passed.','on earth 放在疑问词后加强语气，表达惊讶或不解。','经理对警报为何未响感到强烈疑惑。'),M('“Why on earth the warning system stayed silent?” the manager asked without an auxiliary verb.','“Why on earth did the warning system stay silent?” the manager asked.','一般过去时疑问句需要 did，随后实义动词用原形 stay。','grammar'),[q('What did the manager want to know?','why the warning system stayed silent','where the olive trees grew','who cooked the omelet','经理想知道警报系统为什么没有响。'),q('What does on earth add after why?','strong emphasis or surprise','a literal location on the planet','a condition for borrowing a key','on earth 在疑问词后用于加强语气。',1,'meaning'),q('When did the manager ask the question?','after the storm passed','before the warning system was installed','during the Olympic opening ceremony','风暴过去后经理提出疑问。',1,'context'),q('Which question is grammatically correct?','How on earth did the radio turn itself off?','How on earth the radio turned itself off?','How did on earth the radio turned itself off?','did 应放在主语前，主句动词用原形。',1,'grammar')]);
P('on the internet','On the internet is a prepositional phrase meaning using or available through the internet.',C('on the internet.s1','在网上','The museum posted a high-resolution image of the olive mosaic on the internet for students to study.','博物馆把橄榄马赛克的高清图片发布到网上，供学生学习。','The museum posted a high-resolution image / of the olive mosaic / on the internet for students to study.','on the internet 表示通过互联网发布、查找或使用信息。','图片在线发布后可供学生查阅。'),M('The museum posted the image on the internet, but students could access it only by looking at a paper printout offline.','The museum posted the image on the internet so students could view it online.','若只能看离线纸质打印件，就不是通过互联网访问图片。','meaning'),[q('What did the museum post online?','a high-resolution mosaic image','a paper omelet recipe','the harbor’s radio','博物馆发布了马赛克图片。'),q('Which action happens on the internet?','viewing a museum image through a website','reading a printed sign with no connection','placing a bowl on a table','通过网站查看图片是在网上进行的。',1,'meaning'),q('Who could study the posted image?','students','only the mosaic’s artist','the harbor manager only','图片发布到网上供学生学习。',1,'context'),q('Which preposition belongs in “The report is ___ the internet”?','on','at','under','固定搭配是 on the internet。',1,'collocation')]);
P('on the whole','On the whole is a fixed phrase meaning considering all parts together or in general.',C('on the whole.s1','总体上；大体上','On the whole, the olive harvest was successful, although a late frost damaged several trees.','总体来说，橄榄收成不错，尽管晚霜冻坏了几棵树。','On the whole / the olive harvest was successful / although a late frost damaged several trees.','on the whole 用于概括整体情况，同时可承认个别例外。','总体丰收与少数树木受损并不矛盾。'),M('On the whole, the harvest was a complete failure, though every tree produced abundant fruit.','On the whole, the harvest was successful, though a few trees were damaged.','整体失败与所有树木丰收彼此矛盾，应区分整体评价和局部例外。','meaning'),[q('How was the olive harvest overall?','successful despite damage to several trees','a complete failure with no fruit','too early to evaluate','总体收成不错，但少数树木受损。'),q('Which phrase means “considering everything”?','on the whole','on condition','on time','on the whole 表示总体而言。',1,'meaning'),q('What exception does the sentence mention?','a late frost damaged several trees','the trees were moved online','the harvest happened on Thursday','句子补充说晚霜冻坏了几棵树。',1,'context'),q('Why does the sentence use on the whole?','to give a general assessment while allowing exceptions','to specify the exact harvest date','to show that a radio is switched on','该短语用于概括整体，同时承认局部情况。',1,'usage')]);
P('on time','On time is a fixed phrase meaning at the planned or scheduled time, neither late nor early.',C('on time.s1','准时','The last bus arrived on time, so the night-shift workers reached the station before their train departed.','末班公交准时到达，因此夜班工人在火车开出前赶到了车站。','The last bus arrived on time / so the night-shift workers reached the station / before their train departed.','on time 表示按计划时间准点发生。','公交按时到站，使乘客赶上火车。'),M('The bus arrived on time two hours after its scheduled departure.','The bus arrived late, two hours after its scheduled departure.','晚两小时到达属于迟到，不是准时。','meaning'),[q('When did the bus arrive?','at its scheduled time','two hours after the train left','before the route was announced','on time 表示按预定时间到达。'),q('Which phrase contrasts with on time here?','late','on the whole','on top of','迟到与准时相反。',1,'meaning'),q('Why did the workers reach the station in time?','the bus arrived as scheduled','the train was canceled','the bus stopped at the olive farm','公交准点抵达，使他们赶上火车。',1,'context'),q('Which sentence uses on time correctly?','The lecture began on time at six.','The lecture began on time after a two-hour delay.','The lecture began on time under the table.','按计划六点开讲才是准时。',1,'grammar')]);
P('on top of','On top of means on the highest surface of something; it can also mean immediately after or in addition to something.',[C('on top of.s1','在……顶部','A small olive branch rested on top of the folded map that showed the route to the farmhouse.','一根小橄榄枝放在折叠地图的最上面，地图标出了去农舍的路线。','A small olive branch rested on top of the folded map / that showed the route / to the farmhouse.','on top of 可指位于某物最高表面。','橄榄枝放在地图上方。'),C('on top of.s1','紧接；另外还','On top of the late frost, the harvest team faced a broken press that delayed the olive-oil production.','除了晚霜之外，收获团队还遇到榨油机故障，橄榄油生产因此延误。','On top of the late frost / the harvest team faced a broken press / that delayed olive-oil production.','on top of 也可表示除已有情况外还发生另一件事。','霜冻之外又有设备故障。')],M('On top of the late frost, the team faced no other problem, including the broken press that stopped production.','On top of the late frost, the team also faced a broken press that stopped production.','例句说明霜冻之外还有故障，不能说没有其他问题。','meaning'),[q('What lay on the folded map?','a small olive branch','the broken press','a bus timetable','橄榄枝放在折叠地图上。'),q('What problem came on top of the frost?','a broken olive press','a working radio','a successful harvest','霜冻之外，榨油机也坏了。',1,'context'),q('Which use means “in addition to”?','On top of the delay, the train lost a wheel.','The cup is on top of the table.','The map rests on top of the book.','第一句表示除了延误之外又出了问题。',1,'meaning'),q('Which phrase describes a physical position?','The branch rested on top of the map.','On top of the frost, the press broke.','On top of being late, he forgot the key.','第一句说明枝条在地图表面上方。',1,'distinction')]);
P('on-site','On-site combines on and site and describes work or services happening at the place where they are needed.',C('on-site.s1','现场的；在场发生的','The company sent an on-site technician to repair the observatory’s telescope before the evening session.','公司派了一名现场技术员，在晚间观测开始前修理天文台望远镜。','The company sent an on-site technician / to repair the observatory’s telescope / before the evening session.','on-site 作形容词表示在相关地点现场进行。','技术员到天文台现场修理设备。'),M('The observatory hired an on-site technician who repaired the telescope from a different country and never visited the building.','The observatory hired an on-site technician who repaired the telescope at the building.','未到现场远程工作的技术员不符合此处 on-site 的含义。','meaning'),[q('Where did the technician repair the telescope?','at the observatory','from an unrelated office abroad','inside an online novel','on-site 表示在天文台现场工作。'),q('Which service is on-site?','a nurse working at the school clinic','a support agent who never visits the building','a website that lists repair advice','on-site 服务在所需地点提供。',1,'meaning'),q('When was the repair needed?','before the evening session','after the observatory closed for the year','during the olive harvest','修理在晚间观测开始前完成。',1,'context'),q('How is on-site formed?','on + site','one + side','onion + site','该复合词由 on 和 site 组成。',1,'word-formation')]);
P('once','Once comes from Old English ānes, “one time”; it can mean one occasion, a past period, or as soon as a condition is met.',[C('once.s1','一次；一回','The diver checked the air gauge once before entering the water and then followed the safety checklist.','潜水员下水前检查了一次气压表，随后按安全清单操作。','The diver checked the air gauge once / before entering the water / and then followed the safety checklist.','once 作频率副词可表示某事发生一回。','下水前检查了一次。'),C('once.s2','曾经；从前','The old mill once supplied flour to every village along the river, but it is now a museum.','这座老磨坊曾经为河边每个村庄供应面粉，如今已成为博物馆。','The old mill once supplied flour / to every village along the river / but it is now a museum.','once 可表示过去某时如此，但现在已不是这样。','once 与 now 对照过去和现在。'),C('once.s3','一旦；……之后立即','Once the tide falls below the marker, the rescue boat can pass safely beneath the bridge.','一旦潮位降到标记线以下，救援船就能安全通过桥下。','Once the tide falls below the marker / the rescue boat can pass safely / beneath the bridge.','once 可作连词引出条件或“当……之后立即”。','潮位达到条件后，船即可通过。')],M('The old mill once supplied flour, and it still supplies every village today after becoming a museum.','The old mill once supplied flour, but it no longer does so now that it is a museum.','once 表示过去的状态，不能与“现在仍继续供应”同时对应此处语境。','meaning'),[q('How many times did the diver check the gauge?','one time','three times','not at all','once 表示检查了一回。'),q('What did the mill do in the past?','supplied flour to river villages','served as a museum from its opening','operated an online observatory','旧磨坊过去曾为沿河村庄供应面粉。',2,'context'),q('What happens once the tide falls below the marker?','the rescue boat can pass beneath the bridge','the bridge closes permanently','the old mill starts supplying flour','once 引出潮位达到条件后船可通过。',3,'meaning'),q('Which sentence uses once to mean “in the past”?','She once lived beside the river.','She checked the gauge once.','Once the tide falls, the boat can pass.','第一句表示她过去住在河边。',2,'meaning')]);
P('oncoming','Oncoming combines on and coming and describes something approaching you or about to begin.',C('oncoming.s1','迎面而来的；即将到来的','The cyclist moved to the shoulder when she saw an oncoming truck on the narrow road.','在狭窄道路上看到迎面驶来的卡车后，骑车人移到了路肩。','The cyclist moved to the shoulder / when she saw an oncoming truck / on the narrow road.','oncoming 修饰正在接近或即将到来的事物。','卡车正朝骑车人方向驶来。'),M('The cyclist moved aside for the oncoming truck after it had already passed behind her and was traveling away.','The cyclist moved aside for the oncoming truck as it approached her.','已经驶过并远离的卡车不是迎面而来的车辆。','meaning'),[q('What was approaching the cyclist?','a truck','a rescue boat beneath a bridge','an olive tree','oncoming truck 指迎面驶来的卡车。'),q('Which hazard is oncoming?','a vehicle approaching along your lane','a bus that left the station an hour ago','a stationary bicycle rack','oncoming 表示正在接近。',1,'meaning'),q('Why did the cyclist move to the shoulder?','the road was narrow and a truck was approaching','she wanted to inspect an onion crop','she was preparing to begin an online class','迎面有卡车且道路狭窄，所以她靠向路肩。',1,'context'),q('Oncoming can also describe something that is?','about to begin','already finished long ago','located on a table','oncoming 也可指即将开始的事。',1,'meaning')]);
P('one','One comes from Old English ān and can mean the number 1, a person in general, a particular substitute item, or a unique example.',[C('one.s1','数字；一个','Only one lantern remained lit after the storm damaged the rest.','风暴损坏了其他灯笼后，只剩一盏仍亮着。','Only one lantern remained lit / after the storm damaged / the rest.','one 作数词表示数量为一。','剩下一盏灯笼。'),C('one.s2','人们；任何人','One should check the route before setting out on a winter hike.','冬季徒步出发前，人们应先检查路线。','One should check the route / before setting out / on a winter hike.','one 可作正式泛指代词，表示一般的人。','建议面向任何准备徒步的人。'),C('one.s3','那一个；其中之一','I compared the two rescue maps and chose the one with the clearer bridge markings.','我比较了两张救援地图，选了桥梁标记更清楚的那一张。','I compared the two rescue maps / and chose the one / with the clearer bridge markings.','one 可替代前面提过的单数名词，避免重复。','the one 代替其中一张地图。'),C('one.s4','唯一的；某一','The one reason the lantern stayed lit was that its glass shield blocked the wind.','灯笼仍亮着的唯一原因是玻璃罩挡住了风。','The one reason the lantern stayed lit / was that its glass shield / blocked the wind.','one 可强调唯一性，也可用于引出一个具体例子。','one reason 强调只有这一原因。')],M('One should check your route before setting out on a winter hike.','One should check one’s route before setting out on a winter hike.','正式泛指主语 one 后，反身或所属形式通常对应 one’s，而不是 your。','grammar'),[q('How many lanterns remained lit?','one','two','none','风暴后只剩一盏灯笼亮着。'),q('Who should check the route before a winter hike?','people in general','only the map’s printer','the lantern itself','泛指代词 one 表示一般的人。',2,'meaning'),q('Which map did the speaker choose?','the map with clearer bridge markings','the map with no bridge markings','a lantern instead of a map','the one 代替前文提到的那一张地图。',3,'context'),q('What does “the one reason” emphasize?','there was a single reason','there were many unrelated reasons','no reason could be found','one reason 在此强调唯一原因。',4,'meaning')]);
P('one day','One day is a phrase meaning on a particular day in the past or future, often when the exact date is unknown.',C('one day.s1','某天；有一天','One day, the coastal village hopes to reopen the old lighthouse as a small museum.','有朝一日，海滨村庄希望把旧灯塔重新开放为一座小型博物馆。','One day / the coastal village hopes / to reopen the old lighthouse as a small museum.','one day 可指过去或未来某个未具体说明的日子。','hope to reopen 表明这里指将来的某一天。'),M('One day, the village reopened the lighthouse tomorrow after it had already closed it yesterday.','One day, the village hopes to reopen the lighthouse in the future.','同一叙述不能把 one day 的未来计划写成昨天已发生又明天发生。','grammar'),[q('What does the village hope to do?','reopen the lighthouse as a museum','build an oncoming truck','close the river bridge forever','村庄希望重新开放旧灯塔。'),q('When will it happen?','on an unspecified day in the future','at exactly noon today','every morning without exception','one day 表示未确定的某一天。',1,'meaning'),q('What will the lighthouse become?','a small museum','a nursery','an online bus station','灯塔计划改作小型博物馆。',1,'context'),q('Which sentence uses one day for a future hope?','One day, I will sail across the bay.','I visit the lighthouse once each week.','The lighthouse is on the internet.','will sail 表明 one day 指将来的某一天。',1,'grammar')]);
P('one time','One time combines one and time and means on one occasion or at a particular time in the past.',C('one time.s1','一次；曾经','One time, the ferry crossed the bay in thick fog, and the captain later described how he used the shoreline lights.','有一次，渡船在浓雾中横渡海湾，船长后来讲述了如何借助岸边灯光导航。','One time / the ferry crossed the bay in thick fog / and the captain later described how he used the shoreline lights.','one time 可表示某一次经历，也可引出过去的一个时点。','故事讲述一次具体的航行经历。'),M('One time, the ferry crosses the bay yesterday in thick fog.','One time, the ferry crossed the bay yesterday in thick fog.','过去的 yesterday 与一般现在时 crosses 不匹配，应用过去式 crossed。','verb-form'),[q('What happened one time?','the ferry crossed the bay in thick fog','the lighthouse opened every day','the village planted an onion field','one time 引出渡船的一次经历。'),q('What did the captain later explain?','how he used shoreline lights','how to make an omelet','how to operate an on-site nursery','船长讲述了如何利用岸边灯光。',1,'context'),q('Which phrase is closest in meaning to one time here?','on one occasion','every time','at no time','one time 表示某一次。',1,'meaning'),q('Which verb form fits a one-time event yesterday?','crossed','cross','will cross','yesterday 需要过去式 crossed。',1,'grammar')]);
P('one way or another','One way or another is an idiom meaning by some method, even if the exact method is not known.',C('one way or another.s1','以某种方式；无论如何','The team will get the stranded hikers home one way or another, even if the mountain road stays closed.','即使山路继续封闭，救援队也会想办法把受困的徒步者送回家。','The team will get the stranded hikers home / one way or another / even if the mountain road stays closed.','该习语表示具体办法未定，但最终会设法做到。','山路封闭仍不会阻止救援队完成目标。'),M('The team promised to rescue the hikers one way or another, but said it would make no attempt by any method.','The team promised to find a way to rescue the hikers despite the closed road.','承诺无论如何设法营救，与完全不尝试相矛盾。','meaning'),[q('What will the rescue team do?','get the hikers home','close the mountain road','leave the hikers without help','救援队承诺送受困者回家。'),q('What does one way or another mean?','by some method, even if it is not specified','in only one exact direction','at the same time every day','习语表示用某种办法实现，具体方式未定。',1,'meaning'),q('What obstacle may remain?','the mountain road may stay closed','the hikers have already arrived home','the team has no destination','山路仍可能封闭。',1,'context'),q('Which sentence uses this idiom naturally?','We will finish the repairs one way or another.','One way or another is painted olive.','She bought an one way or another ticket.','该习语常用于表达无论如何会完成某事。',1,'usage')]);
P('one-sided','One-sided combines one and side with -ed and describes a view or decision that considers only one side and may be unfair.',C('one-sided.s1','片面的','The report gave a one-sided account of the dispute because it quoted only the factory owners and ignored the residents.','报告只引用工厂主的说法而忽略居民意见，因此对争议的叙述有失偏颇。','The report gave a one-sided account / of the dispute / because it quoted only the factory owners and ignored the residents.','one-sided 常批评只考虑争论一方、不够公正的陈述。','报告省略了居民一方的观点。'),M('The report was one-sided because it carefully included every group’s evidence and gave both sides equal space.','The report was one-sided because it included the factory owners’ evidence but ignored the residents.','平等呈现各方证据与片面报道相反。','meaning'),[q('Why was the report one-sided?','it quoted owners but ignored residents','it included every group equally','it studied only a one-way ticket','报告只引用工厂主而忽略居民。'),q('Which account is one-sided?','a debate summary that reports only one participant’s claims','a report that carefully compares all viewpoints','a balanced account with evidence from both groups','one-sided 指只呈现一方、可能不公正。',1,'meaning'),q('Whose views did the report leave out?','the residents’','the factory owners’','the report editor’s only','报告忽略了居民的意见。',1,'context'),q('How is one-sided formed?','one + side + -ed','on + site + -ed','one + time + -ness','该词由 one、side 和 -ed 组成。',1,'word-formation')]);
P('one-time','One-time combines one and time; as an adjective it can mean former or happening on a single occasion.',[C('one-time.s1','昔日的；从前的','The one-time captain now teaches sailing at the harbor school instead of commanding a ferry.','这位昔日的船长如今在港口学校教帆船，而不再指挥渡船。','The one-time captain / now teaches sailing / at the harbor school instead of commanding a ferry.','one-time 可作形容词表示过去曾任某职或过去曾有某种身份。','now 与 one-time 对照过去和现在。'),C('one-time.s1','一次性的','The lab ran a one-time test on the water sample before beginning its monthly monitoring program.','实验室在开始每月监测计划前，对水样做了一次性检测。','The lab ran a one-time test / on the water sample / before beginning its monthly monitoring program.','one-time 也可指只发生一次的行为或测试。','测试与后续每月监测形成对比。')],M('The one-time test was repeated every day for a year and formed the lab’s daily monitoring program.','The one-time test was performed on a single occasion before regular monitoring began.','每天持续一年的测试不是一次性测试。','meaning'),[q('What does the one-time captain do now?','teaches sailing','commands the same ferry','repairs an olive press','他如今在学校教帆船。'),q('How often did the lab run the one-time test?','once before regular monitoring','every day for a year','once each month forever','one-time test 只做了一次。',1,'context'),q('Which use means “former”?','a one-time mayor who now teaches history','a one-time test completed yesterday','a one-way ticket to the harbor','former mayor 指过去曾任市长。',1,'meaning'),q('Which use means “happening only once”?','a one-time inspection','a one-time captain from the past','a one-sided report','一次性检查只发生一次。',1,'meaning')]);
P('one-way ticket','One-way ticket combines one-way and ticket; it is a ticket for a journey to a destination without a return trip included.',C('one-way ticket.s1','单程票','She bought a one-way ticket to the island because her research stay would last several months.','由于研究将持续数月，她买了一张去岛上的单程票。','She bought a one-way ticket to the island / because her research stay / would last several months.','one-way ticket 只包括前往目的地的单程旅程。','长期停留解释了她为何不预订返程。'),M('She bought a one-way ticket to the island, which included a return journey back the next morning.','She bought a one-way ticket to the island without a return journey.','包含返程的票不是单程票。','meaning'),[q('Where was she traveling?','to the island','back from the island the next morning','to the Olympic stadium','她买票去岛上。'),q('What does a one-way ticket exclude?','a return trip','the outward journey','the passenger’s name','单程票不包含返程。',1,'meaning'),q('Why did she not book a return journey?','her research stay would last several months','the island had no ferry station','the ticket was for an omelet','研究停留时间较长，所以只买单程票。',1,'context'),q('Which ticket is one-way?','a ticket from the city to the island only','a ticket from the city to the island and back','a pass valid for every bus route','one-way ticket 只覆盖去程。',1,'distinction')]);
P('oneness','Oneness is formed from one plus -ness and means unity, identity, or the state of being a single whole.',C('oneness.s1','单一性；合一','The dancers moved in oneness, matching each other’s pace so closely that the group seemed to breathe together.','舞者们步调一致地移动，彼此节奏如此协调，仿佛整个团体在共同呼吸。','The dancers moved in oneness / matching each other’s pace / so closely that the group seemed to breathe together.','oneness 指协调一致、合为一体的状态。','舞者同步移动呈现整体感。'),M('The dancers moved in oneness by performing unrelated steps at different times and refusing to coordinate.','The dancers moved in oneness by coordinating their pace and movements.','动作彼此无关且不同步，不能形成合一或协调状态。','meaning'),[q('How did the dancers move?','in close coordination','one at a time with no shared rhythm','in opposite directions without noticing','他们步调协调，仿佛共同呼吸。'),q('What does oneness describe?','a state of unity or being a whole','a one-way journey','a former job title','oneness 指合一或整体状态。',1,'meaning'),q('What created the impression of unity?','the dancers matched each other’s pace','each dancer followed a different rhythm','the stage lights turned off','同步的节奏让团体显得浑然一体。',1,'context'),q('Which suffix turns one into oneness?','-ness','-er','-ous','-ness 可将形容词或数词相关词构成状态名词。',1,'word-formation')]);
P('ones','Ones is the plural of the pronoun one and is used to refer to previously mentioned things instead of repeating their noun.',C('ones.s1','……的那些','The shop displayed several rescue helmets, and the red ones had reflective strips for night work.','商店陈列着几顶救援头盔，红色的那些带有夜间作业用的反光条。','The shop displayed several rescue helmets / and the red ones / had reflective strips for night work.','ones 可替代前文提过的复数名词，避免重复。','red ones 指前文提到的红色头盔。'),M('The shop displayed several helmets, and the red one had reflective strips, referring to all of the helmets.','The shop displayed several helmets, and the red ones had reflective strips.','指多顶红色头盔时应使用复数 ones。','plural'),[q('What did the shop display?','rescue helmets','one-way tickets','olive branches','商店陈列救援头盔。'),q('What does “the red ones” refer to?','the red helmets','red reflective strips only','the shop’s rescue workers','ones 代替前文的复数名词 helmets。',1,'context'),q('Which sentence correctly uses ones to avoid repetition?','I tried two jackets and bought the blue ones.','I tried two jackets and bought the blue one, meaning both.','I tried two jacket and bought the blue ones.','复数 ones 指两件蓝色夹克，名词 jackets 也用复数。',1,'grammar'),q('Why use ones instead of repeating helmets?','to refer back to the plural noun without repeating it','to describe one person in general','to indicate a single journey','ones 可替代前文的复数名词。',1,'meaning')]);
P('oneself','Oneself combines one and self and is a reflexive pronoun for a general person; it can also emphasize acting personally or alone.',[C('oneself.s1','自己（泛指反身）','One should prepare oneself for sudden changes in mountain weather before starting the climb.','开始攀登前，人们应让自己为山区天气突变做好准备。','One should prepare oneself / for sudden changes in mountain weather / before starting the climb.','oneself 与泛指主语 one 对应，作反身代词。','主语 one 和宾语 oneself 指同一泛指的人。'),C('oneself.s2','亲自；独自','Rather than hiring a decorator, the owner painted the small harbor office oneself.','店主没有雇装修工，而是亲自粉刷了港口小办公室。','Rather than hiring a decorator / the owner painted the small harbor office / oneself.','oneself 可用于强调某人亲自行动或独自完成。','店主没有雇人，强调自己动手。')],M('One should prepare yourself for sudden changes in mountain weather.','One should prepare oneself for sudden changes in mountain weather.','泛指主语 one 应与反身代词 oneself 保持人称一致。','grammar'),[q('Who should prepare for changing weather?','a person in general','only the mountain itself','the oncoming truck','泛指代词 one 表示一般徒步者。'),q('What did the owner do oneself?','painted the harbor office','hired a decorator to paint it','bought a one-way ticket','店主亲自粉刷了办公室。',2,'context'),q('Which reflexive pronoun matches one?','oneself','yourself','themselves','one 与 oneself 对应。',1,'grammar'),q('What does oneself emphasize in the second example?','the owner did the work personally','the work was done online','the office belongs to several people','此处 oneself 强调店主亲自完成。',2,'meaning')]);
P('onetime','Onetime is formed from one and time and means formerly so, or occurring on a single occasion.',[C('onetime.s1','昔日的','The onetime mayor now works as a volunteer guide at the harbor museum.','这位昔日的市长如今在港口博物馆做志愿导览员。','The onetime mayor / now works as a volunteer guide / at the harbor museum.','onetime 作形容词可表示过去曾有某种身份或地位。','now 与过去的市长身份形成时间对照。'),C('onetime.s2','一次性的','The crew made a onetime inspection of the pier before reopening it to the public.','码头重新向公众开放前，工作人员对其进行了一次性检查。','The crew made a onetime inspection / of the pier / before reopening it to the public.','onetime 也可表示只发生一次。','重新开放前只安排了一次检查。')],M('The onetime mayor is still the current mayor and has never held any other role.','The onetime mayor formerly led the city and now works as a museum guide.','onetime 表示过去曾是某身份，与“仍是现任且从未卸任”相冲突。','meaning'),[q('What does the onetime mayor do now?','volunteer at the harbor museum','serve as mayor today','inspect the pier every week','他现在在博物馆做志愿导览员。'),q('How many inspections did the crew make?','one inspection','one every day for a year','none before reopening','onetime inspection 指一次性检查。',2,'context'),q('Which use means “formerly”?','a onetime captain who now teaches','a onetime test performed once','a one-way ticket for a trip','former captain 指过去曾担任船长。',1,'meaning'),q('Which use means “occurring once”?','a onetime survey before construction','a onetime mayor from the past','a continuous monthly review','一次性调查只发生一回。',2,'meaning')]);
P('ongoing','Ongoing combines on and going and describes something continuing without being finished or something lasting and developing over time.',[C('ongoing.s1','持续的；仍在进行的','The police said the investigation into the missing harbor records was ongoing and asked witnesses not to speculate.','警方表示，港口记录失踪案仍在调查中，并请目击者不要猜测。','The police said the investigation / into the missing harbor records / was ongoing.','ongoing 表示尚未结束、正在继续的过程。','警方仍在调查，因此案件尚未结束。'),C('ongoing.s2','长期存在并发展','The town maintains an ongoing partnership with the island school to exchange teachers and marine-science materials.','小镇与岛上的学校保持长期合作，持续交流教师和海洋科学资料。','The town maintains an ongoing partnership / with the island school / to exchange teachers and marine-science materials.','ongoing 也可描述长期持续、不断发展的关系或项目。','教师和资料交换体现长期合作。')],M('The investigation was ongoing because police had completed every interview, filed the final report, and closed the case.','The investigation was ongoing because police were still interviewing witnesses and had not filed a final report.','案件已结案且调查结束，与 ongoing 相反。','meaning'),[q('What was still happening in the first example?','the investigation into missing records','the exchange of teachers only','the harbor museum’s weekly tour','警方仍在调查记录失踪案。'),q('What does the town’s ongoing partnership involve?','continued exchange with the island school','a single visit that ended years ago','a one-time ticket purchase','ongoing 描述持续发展的合作关系。',2,'context'),q('Which task is ongoing?','a review that is continuing and not yet finished','a report filed and closed yesterday','a test performed once and completed','ongoing 表示仍在进行、尚未结束。',1,'meaning'),q('Which ongoing use refers to a long-term relation?','an ongoing partnership between two schools','an ongoing investigation into one incident','an ongoing minute on a clock','长期合作属于持续发展的关系。',2,'distinction')]);
P('onion','Onion comes through Old French from Latin unio, “large pearl”; it names the vegetable and can also mean a serving or flavor of it.',[C('onion.s1','洋葱','She chopped a red onion and added it to the lentil soup with garlic and cumin.','她切碎一个红洋葱，和大蒜、孜然一起加入扁豆汤。','She chopped a red onion / and added it to the lentil soup / with garlic and cumin.','onion 指有辛香味、外皮纸质的圆形蔬菜。','红洋葱作为食材加入汤中。'),C('onion.s2','洋葱味的一份食物','At the café, I ordered an onion with my baked potato, and the server brought a small bowl of sautéed onions.','在咖啡馆，我点了土豆配洋葱，服务员端来一小碗炒洋葱。','At the café / I ordered an onion with my baked potato / and the server brought a small bowl of sautéed onions.','onion 也可指作为配料或一份食物的洋葱。','一小碗炒洋葱表明这里指食物份量。')],M('She added a red onion to the soup by pouring in a small bowl of sautéed onions without using the vegetable.','She added a red onion to the soup by chopping the vegetable and stirring it in.','例句要加入一个洋葱蔬菜，而不是将炒洋葱碗倒作同一件事。','meaning'),[q('What did she chop for the soup?','a red onion','a harbor record','an Olympic medal','她切碎了一个红洋葱。'),q('What did the café server bring?','a small bowl of sautéed onions','a whole oncoming truck','a one-time mayor','点餐后端来一小碗炒洋葱。',2,'context'),q('Which phrase treats onion as a serving of food?','I ordered an onion with my baked potato.','The onion plant has papery skin.','She chopped a red onion.','第一句指点的一份洋葱配菜。',2,'meaning'),q('What is onion’s historical Latin source cited here?','unio, “large pearl”','omnis, “all”','ōnes, “once”','onion 的词源经古法语关联到拉丁语 unio。',1,'word-formation')]);
P('online','Online combines on and line; it can mean available or done through the internet, or connected to a computer network at the moment.',[C('online.s1','在线的；网上的','The harbor museum made its ship log available online so researchers could search the records from home.','港口博物馆把航海日志放到网上，研究人员在家也能检索记录。','The harbor museum made its ship log available online / so researchers could search the records / from home.','online 可表示通过互联网提供或完成。','研究人员可从家中在线检索日志。'),C('online.s2','连网状态','The printer is online again after the technician restored its connection to the office network.','技术员恢复打印机与办公室网络的连接后，它又重新连网了。','The printer is online again / after the technician restored its connection / to the office network.','online 也可描述设备此刻已连接到计算机网络。','恢复连接后打印机进入在线状态。')],M('The printer was online because its network cable was disconnected and it could not communicate with the office system.','The printer was online because its network connection had been restored.','断开网络且不能通信的打印机不是在线状态。','meaning'),[q('Where could researchers search the ship log?','from home through the museum’s website','only inside a paper archive','on the printer’s control panel','日志可在线访问。'),q('What happened to the printer?','it reconnected to the office network','it was moved to an island','it received a one-way ticket','打印机恢复了网络连接。',2,'context'),q('Which use means available through the internet?','The museum’s records are online.','The printer is online again.','The technician is on-site.','第一句描述记录可以通过互联网访问。',1,'meaning'),q('Which use describes a device’s current connection state?','The printer is online.','The ship log is online for readers.','The museum posted a notice on the internet.','printer is online 描述设备此刻连上网络。',2,'distinction')]);
P('onlooker','Onlooker combines on, look, and -er and means a person who watches an event without taking part.',C('onlooker.s1','围观者','An onlooker called emergency services after a cyclist fell, while others kept the road clear.','一名围观者在骑车人摔倒后拨打了急救电话，其他人则保持道路畅通。','An onlooker called emergency services / after a cyclist fell / while others kept the road clear.','onlooker 指观看事件但没有参与其中的人。','围观者观察事故并寻求帮助，而未参与事故本身。'),M('The onlooker raced in the event and crossed the finish line before the competitors.','The onlooker watched the event from the roadside without taking part.','参加比赛并冲过终点的人是参赛者，不是旁观者。','distinction'),[q('What happened to the cyclist?','the cyclist fell','the cyclist won the Olympic Games','the cyclist planted an onion','骑车人摔倒了。'),q('What did the onlooker do?','called emergency services','competed in the race','repaired the bicycle before the fall','围观者打电话求助，没有参加比赛。',1,'context'),q('Who is an onlooker?','a person who watches but does not participate','a contestant in the event','an official who starts the race','onlooker 指旁观者。',1,'meaning'),q('Which parts form onlooker?','on + look + -er','one + time + -ly','onion + look + -er','onlooker 由 on、look 和表示人的 -er 构成。',1,'word-formation')]);
P('only','Only comes from Old English anlic, “one-like”; it can mean no more than, the sole one, or but with a limit or qualification.',[C('only.s1','只；仅仅','The lighthouse is only two kilometers from the harbor, so the rescue crew can reach it quickly.','灯塔离港口只有两公里，因此救援队能很快到达。','The lighthouse is only two kilometers / from the harbor / so the rescue crew can reach it quickly.','only 可限制数量或程度，表示“仅仅、只有”。','两公里是灯塔与港口的距离。'),C('only.s2','唯一的','Mira was the only volunteer who knew how to operate the old lighthouse lamp.','米拉是唯一知道如何操作旧灯塔灯具的志愿者。','Mira was the only volunteer / who knew how to operate / the old lighthouse lamp.','only 可作形容词强调没有其他同类的人或物。','只有米拉会操作旧灯具。'),C('only.s3','可是；不过','I would join the harbor tour, only I have to work until the last ferry leaves.','我本来想参加港口导览，不过我得工作到末班渡船离开。','I would join the harbor tour / only I have to work / until the last ferry leaves.','only 也可作连词，补充一个限制或不便，相当于 but。','工作时间是参加导览的障碍。')],M('Mira was the only volunteer who knew the lamp, although every volunteer knew how to operate it.','Mira was the only volunteer who knew how to operate the lamp.','only 表示没有其他同类者，与“每个志愿者都会”矛盾。','meaning'),[q('How far is the lighthouse from the harbor?','two kilometers','one hundred kilometers','the exact length of the ferry','only 限制距离为两公里。'),q('Who could operate the old lamp?','Mira alone','every volunteer','the ferry captain only','only volunteer 表示米拉是唯一会操作灯的人。',2,'context'),q('Why will the speaker miss the harbor tour?','work continues until the last ferry leaves','the tour is only two kilometers long','Mira is the only volunteer','only 在句中引出参加不了的限制。',3,'meaning'),q('Which use means “no more than”?','The box is only five kilograms.','She was the only volunteer.','I would go, only I am working.','第一句中 only 限制重量。',1,'meaning')]);
P('onrushing','Onrushing combines on and rushing and describes something moving forward rapidly and forcefully.',C('onrushing.s1','汹涌冲来的','The driver saw an onrushing wave sweep across the coastal road and steered toward higher ground.','司机看到一股汹涌海浪冲过沿海道路，便把车驶向高处。','The driver saw an onrushing wave / sweep across the coastal road / and steered toward higher ground.','onrushing 修饰快速而有力地向前冲来的事物。','海浪迅速冲上道路，司机及时避让。'),M('The driver called the wave onrushing because it was still and motionless far offshore.','The driver called the wave onrushing because it rushed forcefully across the road.','静止在远海的波浪没有向前冲来的动作。','meaning'),[q('What moved across the coastal road?','a wave','an onlooker','a one-way ticket','海浪冲过了沿海道路。'),q('What should onrushing describe?','a forceful movement toward someone or something','a motionless object far away','a former mayor','onrushing 指快速、有力地冲来。',1,'meaning'),q('Where did the driver steer?','toward higher ground','onto the wave','back into the water','看到海浪后，司机驶向高处。',1,'context'),q('Which word is closest to onrushing in the example?','surging','stationary','former','海浪汹涌冲来，surging 最接近。',1,'meaning')]);
P('onset','Onset comes from on plus set, “a setting upon”; it means a beginning, especially of something unwelcome, or the start of an illness.',[C('onset.s1','开始；来临','At the onset of winter, the harbor closes its outer pier because freezing spray makes the walkway unsafe.','冬季来临时，港口会关闭外侧码头，因为结冰的浪花会让步道变得危险。','At the onset of winter / the harbor closes its outer pier / because freezing spray makes the walkway unsafe.','onset 可指某事的开始，尤常用于不愉快情况。','冬季开始带来结冰风险。'),C('onset.s2','疾病发作','The patient reported numbness at the onset of the migraine, before the severe headache began.','患者说偏头痛发作之初先出现了麻木，之后才开始剧烈头痛。','The patient reported numbness / at the onset of the migraine / before the severe headache began.','医学语境中 onset 指疾病或症状开始发作。','麻木出现在偏头痛的早期。')],M('At the onset of the migraine, the patient reported symptoms only after the illness had completely ended.','At the onset of the migraine, the patient reported numbness before the severe headache began.','onset 指疾病开始时，而不是疾病完全结束之后。','meaning'),[q('Why did the harbor close the outer pier?','freezing spray made the walkway unsafe','an onlooker called about an olive tree','the tide was below the marker','冬季开始后结冰浪花造成安全风险。'),q('What symptom appeared at the onset of the migraine?','numbness','a cracked opal','a one-sided report','偏头痛发作之初出现了麻木。',2,'context'),q('Which event is an onset?','the beginning of a severe storm','the end of a storm after clear weather returns','a routine inspection next year','onset 指某过程或情况的开始。',1,'meaning'),q('In a medical report, onset most nearly means?','the start of a disease or symptom','the treatment’s final result','a tool for opening a bottle','医学语境中的 onset 指疾病开始发作。',2,'meaning')]);
P('onshore','Onshore combines on and shore; it can mean located on land rather than at sea or moving toward/being at the shore.',[C('onshore.s1','岸上的；国内的','The company moved its onshore data center inland to protect the servers from storm surges.','公司把岸上的数据中心迁到内陆，以保护服务器免受风暴潮侵袭。','The company moved its onshore data center inland / to protect the servers / from storm surges.','onshore 可作形容词，指位于陆地或本国境内。','数据中心在海上还是陆地会影响防灾规划。'),C('onshore.s2','向岸上；在岸上','By dawn, a steady wind was blowing onshore and pushing small waves toward the beach.','黎明时分，稳定的风正向岸上吹，把小浪推向海滩。','By dawn / a steady wind was blowing onshore / and pushing small waves toward the beach.','onshore 也可作副词，表示朝海岸方向或在岸上。','风由海面吹向陆地。')],M('The wind was blowing onshore from the beach out toward the open sea.','The wind was blowing offshore from the beach out toward the open sea.','从海滩吹向外海是 offshore；onshore 风向则朝岸上。','distinction'),[q('Where was the data center located?','on land','on a boat far offshore','inside the harbor museum','onshore 形容位于陆地的数据中心。'),q('Which way did the dawn wind blow?','from the sea toward the beach','from the beach out to sea','straight upward from the pier','onshore 表示风向岸边吹。',2,'context'),q('Which phrase means “located on land”?','an onshore terminal','an offshore platform','an oncoming vehicle','onshore 可形容陆地上的设施。',1,'meaning'),q('What is the opposite direction of an onshore wind?','offshore','onstage','onward','offshore 风由岸吹向海上，与 onshore 相反。',1,'distinction')]);
P('onslaught','Onslaught is recorded as a borrowing or adaptation of Dutch aanslag, “attack”; its early spelling history is uncertain, but it now means a violent attack or sudden flood of criticism or work.',[C('onslaught.s1','猛烈攻击','The fort endured an onslaught from enemy forces but held its gate until reinforcements arrived.','堡垒遭到敌军猛攻，但在援军抵达前一直守住了城门。','The fort endured an onslaught / from enemy forces / but held its gate until reinforcements arrived.','onslaught 可指猛烈的军事或身体攻击。','敌军持续猛攻堡垒。'),C('onslaught.s1','大量涌来；猛烈抨击','After the festival, the help desk faced an onslaught of messages from visitors who had lost their tickets.','节庆结束后，服务台收到大量游客发来的消息，他们都丢了门票。','After the festival / the help desk faced an onslaught of messages / from visitors who had lost their tickets.','onslaught 也可比喻突然大量涌来的工作、信息或批评。','短时间内大量求助消息涌入。')],M('The help desk faced an onslaught of messages because only one visitor contacted it all day.','The help desk faced an onslaught of messages because hundreds of visitors contacted it at once.','单独一条消息不能构成大量突然涌入的 onslaught。','meaning'),[q('What did the fort withstand?','an attack by enemy forces','a wave of visitor messages','an onshore wind','堡垒承受的是敌军攻击。'),q('Why was the help desk overwhelmed?','many visitors sent messages after losing tickets','only one visitor sent a message','the fort closed the outer pier','节后大量游客同时求助。',1,'context'),q('Which event is an onslaught in the figurative sense?','a sudden flood of complaints after a service outage','one quiet question from a visitor','a routine weekly meeting','比喻义指突然大量涌来的批评或工作。',1,'meaning'),q('What does the source say about the word’s early spelling history?','it is uncertain','it is certainly from Latin for “open”','it is formed from onstage and olive','词源资料指出早期拼写和形式的历史不确定。',1,'word-formation')]);
P('onstage','Onstage combines on and stage; it means in the performing area or happening/placed on the stage.',[C('onstage.s1','在前台','The actor walked onstage after the curtain rose and bowed to the audience.','幕布升起后，演员走上前台向观众鞠躬。','The actor walked onstage / after the curtain rose / and bowed to the audience.','onstage 可指演员进入表演区域，区别于后台。','走上台后演员面对观众鞠躬。'),C('onstage.s2','台上的','A small olive branch was the only onstage decoration during the minimalist scene.','极简场景中，台上唯一的装饰是一根小橄榄枝。','A small olive branch was the only onstage decoration / during the minimalist scene.','onstage 也可作形容词，表示在舞台上出现或摆放。','橄榄枝是舞台布景的一部分。')],M('The actor remained offstage in the dressing room while the review said he walked onstage to bow.','The actor walked onstage to bow to the audience after the curtain rose.','留在更衣室后台与走上舞台鞠躬是相反的动作。','meaning'),[q('When did the actor walk onstage?','after the curtain rose','before the theater was built','during the ticket sale online','演员在幕布升起后走上舞台。'),q('What was the only onstage decoration?','a small olive branch','a lighthouse placed in the harbor','a red rescue truck','橄榄枝是台上的唯一装饰。',2,'context'),q('Which sentence uses onstage as an adverb?','The singer stepped onstage to greet the crowd.','The onstage microphone was switched off.','The play’s onstage set included a bench.','第一句中 onstage 修饰 stepped，表示走到台上。',1,'grammar'),q('Which phrase describes an object placed on the stage?','an onstage prop','an oncoming truck','an onshore wind','onstage 可作形容词描述舞台上的道具。',2,'meaning')]);
P('ontario','Ontario is named from Mohawk (Iroquoian) ontari:io, interpreted as “beautiful lake” or “great lake”; it names the Canadian province and a Great Lake.',C('ontario.s1','安大略','The research team drove across Ontario from Toronto to visit three inland wetlands.','研究团队从多伦多出发，开车横穿安大略省，探访三处内陆湿地。','The research team drove across Ontario / from Toronto / to visit three inland wetlands.','Ontario 可指以多伦多为首府的加拿大省份。','从多伦多横穿该地区前往湿地。'),M('The team crossed Ontario from Toronto, although Ontario is a city whose capital is the province of Canada.','The team crossed Ontario from Toronto, although Ontario is a Canadian province with Toronto as its capital.','Ontario 是省份，Toronto 是其首府城市，不能把两者关系颠倒。','distinction'),[q('Where did the research team begin its drive?','Toronto','the Lake Ontario shoreline only','the harbor museum','研究团队从多伦多出发。'),q('What is Ontario in the first example?','a Canadian province','a type of onshore wind','a one-way ticket','Ontario 指加拿大的省份。',1,'meaning'),q('What did the team visit?','three inland wetlands','an Olympic stadium','a lighthouse on the stage','他们前往探访三处内陆湿地。',1,'context'),q('What does the Mohawk name ontari:io mean in the cited source?','beautiful lake or great lake','a field of onions','a road moving onward','词源资料给出“美丽的湖”或“大湖”两种解释。',1,'word-formation')]);
P('onto','Onto combines on and to; it can describe movement to a surface, a shift to a new subject, or realizing a secret.',[C('onto.s1','到……上面','The kitten jumped onto the empty stage and sat beside the folded curtain.','小猫跳上空舞台，坐在折起的幕布旁边。','The kitten jumped onto the empty stage / and sat / beside the folded curtain.','onto 表示移动到某物表面或上方。','jumped onto 描述从别处跳到舞台上。'),C('onto.s2','转向新话题','After discussing the budget, the chair moved onto the question of safety inspections.','讨论完预算后，主席转而讨论安全检查问题。','After discussing the budget / the chair moved onto / the question of safety inspections.','move onto 可表示从一个话题或活动转向另一个。','讨论主题从预算转到检查。'),C('onto.s3','察觉；发现','The detective was onto the forged ticket scheme after noticing the same false stamp on several passes.','侦探发现几张通行证上都有相同的假印章后，察觉了伪造门票的把戏。','The detective was onto the forged ticket scheme / after noticing the same false stamp / on several passes.','be onto someone/something 可表示发现或察觉其秘密。','相同的假印章揭露了伪造计划。')],M('The detective was onto the forgery but noticed no repeated stamp and had no suspicion of any scheme.','The detective was onto the forgery after noticing the repeated false stamp.','既然没有发现线索也毫无怀疑，就不能说侦探已经察觉骗局。','meaning'),[q('Where did the kitten jump?','onto the stage','under the harbor','off the internet','小猫跳到了舞台上。'),q('What subject did the chair move onto?','safety inspections','the olive harvest only','the theater’s ticket price','主席把讨论转到安全检查。',2,'context'),q('What made the detective onto the scheme?','the same false stamp appeared on several passes','the passes were all genuine','the detective saw a kitten onstage','重复的假印章让侦探察觉伪造计划。',3,'meaning'),q('Which sentence uses onto for a physical movement?','She climbed onto the platform.','She was onto the hidden plan.','The meeting moved onto budget issues.','第一句中的 onto 表示移动到平台上。',1,'meaning')]);
P('ontology','Ontology combines Greek ontos, “being,” with -logy, “study”; it means the philosophical study of being or, in computing, a structured set of concepts and relations.',[C('ontology.s1','存在论；本体','The philosophy seminar compared two views in ontology: whether objects exist independently of the mind.','哲学研讨课比较了存在论中的两种观点：事物是否独立于心灵而存在。','The philosophy seminar compared two views in ontology / whether objects exist / independently of the mind.','ontology 在哲学中研究存在及事物的本质。','讨论聚焦对象是否独立存在。'),C('ontology.s1','计算机本体','The database team built an ontology linking bird species, habitats, and conservation statuses so researchers could search related records.','数据库团队建立了一个连接鸟类、栖息地和保护状态的本体，方便研究人员检索相关记录。','The database team built an ontology / linking bird species, habitats, and conservation statuses / so researchers could search related records.','计算机领域的 ontology 是组织概念及其关系的结构化系统。','物种、栖息地和保护状态之间建立了关系。')],M('The database ontology kept every concept unrelated and provided no way to connect species with habitats.','The database ontology linked species with habitats and their conservation statuses.','计算机本体的作用是组织概念关系，完全不关联信息与例句相反。','meaning'),[q('What philosophical question did the seminar discuss?','whether objects exist independently of the mind','whether a ferry ticket includes a return trip','whether the stage curtain is open','研讨课讨论对象是否独立于心灵存在。'),q('Which concepts did the database ontology link?','species, habitats, and conservation status','tickets, omelets, and theater curtains','only unrelated bird names','本体连接物种、栖息地和保护状态。',1,'context'),q('In computing, an ontology is?','a structured set of concepts and their relations','a philosophical view with no concepts','an onshore data center','计算机本体组织概念和关系。',1,'meaning'),q('Which Greek element means “being” in ontology?','ontos','-logy','on','ontos 表示“存在、所是”。',1,'word-formation')]);
P('onward','Onward combines on and -ward; it can mean moving forward without turning back or continuing from a stated time.',[C('onward.s1','向前；继续前进','From the ridge, the hikers continued onward toward the coast rather than returning to the village.','从山脊出发，徒步者继续向海岸前进，而不是返回村庄。','From the ridge / the hikers continued onward toward the coast / rather than returning to the village.','onward 可作副词，表示继续向前或朝某方向。','徒步者没有折返，而是继续前行。'),C('onward.s2','从某时起；以后的','The discount applies to all ferry trips from June onward, including the summer schedule.','这项折扣适用于六月起的所有渡船行程，包括夏季时刻表。','The discount applies to all ferry trips / from June onward / including the summer schedule.','from a time onward 表示从某时起并延续下去。','折扣从六月开始继续有效。')],M('The hikers turned back toward the village but continued onward to the coast without changing direction.','The hikers continued onward toward the coast instead of turning back to the village.','折返与继续朝海岸前进的方向相反。','meaning'),[q('Which direction did the hikers continue?','toward the coast','back to the village','onto the stage','他们继续向海岸前进。'),q('When does the ferry discount begin?','in June and continues after that','only before June','for one trip yesterday only','from June onward 表示六月起持续适用。',2,'context'),q('Which use means “forward without turning back”?','The path leads onward through the valley.','The discount applies from June onward.','The actor walked onstage.','第一句表示沿山谷继续向前。',1,'meaning'),q('In “from June onward,” onward refers to?','a continuing period after June','a movement toward the coast','a past occasion before June','这里 onward 表示从六月起往后。',2,'meaning')]);
P('onwards','Onwards is the adverbial form of onward with an added -s; it means further forward or from a time into the future.',C('onwards.s1','向前；以后','The sign points onwards to the next checkpoint, two kilometers beyond the old lighthouse.','路牌指向前方下一个检查点，它位于旧灯塔以外两公里处。','The sign points onwards / to the next checkpoint / two kilometers beyond the old lighthouse.','onwards 可表示继续朝前方移动或从某时向后延续。','路标指示继续向前走。'),M('The sign pointed onwards to the checkpoint behind the hikers, telling them to turn back and go backward.','The sign pointed onwards to the checkpoint ahead, telling the hikers to continue forward.','onwards 指继续向前，不是向后折返。','meaning'),[q('Where was the next checkpoint?','two kilometers beyond the lighthouse','behind the hikers at the village','inside the harbor museum','检查点在旧灯塔以外两公里处。'),q('What does the sign direct hikers to do?','continue forward','turn backward toward the village','stop and open a book','onwards 表示继续前进。',1,'context'),q('Which phrase means “from that date into the future”?','from Monday onwards','on the stage','on top of the map','from Monday onwards 表示从星期一往后。',1,'meaning'),q('Onwards most nearly means?','further forward','not transparent','without a return ticket','onwards 指继续向前或往后延续。',1,'meaning')]);
P('ooze','Ooze is related to Old English wase, “mud or soft wet ground”; as a verb it means to flow slowly or let a substance flow slowly.',C('ooze.s1','渗出；慢慢流出','Amber sap began to ooze from the cut in the pine trunk after the warm afternoon.','温暖的午后，琥珀色树脂开始从松树树干的切口慢慢渗出。','Amber sap began to ooze / from the cut in the pine trunk / after the warm afternoon.','ooze 描写液体缓慢地流出或渗出。','树脂从伤口处缓慢渗出。'),M('Thick sap oozed from the trunk by remaining completely inside the unbroken bark.','Thick sap oozed from the trunk through a small cut in the bark.','若树皮完整且树脂留在内部，就没有发生渗出。','meaning'),[q('What began to ooze from the pine?','amber sap','an oncoming wave','an opaque map','松树切口处渗出琥珀色树脂。'),q('How did the sap move?','slowly through a cut in the trunk','rapidly as a dry wind','not at all beneath the bark','ooze 表示缓慢流出或渗出。',1,'meaning'),q('When did the resin begin to ooze?','after a warm afternoon','before the pine tree existed','only after it became a museum','温暖的午后树脂开始渗出。',1,'context'),q('Which verb is closest to ooze in this sentence?','seep','shatter','race','ooze 的意思接近 seep，即慢慢渗出。',1,'meaning')]);
P('opal','Opal comes through Latin and Greek from Sanskrit upala, “precious stone”; it is a silica mineral often showing shifting rainbow colors.',C('opal.s1','蛋白石；变彩宝石','The jeweler tilted the opal under a lamp, revealing flashes of blue and green across its milky surface.','珠宝商把蛋白石倾斜到灯下，乳白色表面闪现出蓝色和绿色。','The jeweler tilted the opal under a lamp / revealing flashes of blue and green / across its milky surface.','opal 指常呈乳白色、能显现彩虹般变彩的二氧化硅矿物。','不同角度下出现蓝绿闪光。'),M('The jeweler called the stone an opal even though it was opaque gray glass with no mineral or play of color.','The jeweler called the stone an opal because it showed shifting colors across its silica surface.','普通灰玻璃没有蛋白石的矿物结构和变彩特征。','meaning'),[q('What appeared when the jeweler tilted the stone?','blue and green flashes','a printed schedule','a blacksmith’s hammer','灯下出现蓝色和绿色的闪光。'),q('What property often distinguishes opal?','a play of changing colors','a perfectly transparent, colorless surface only','a metal thread inside it','蛋白石常有随角度变化的彩色闪光。',1,'meaning'),q('What did the jeweler use to reveal the colors?','a lamp','a ferry ticket','an olive branch','珠宝商把蛋白石放到灯下观察。',1,'context'),q('Which Sanskrit word is given as an ancestor of opal?','upala, “precious stone”','ontos, “being”','wase, “mud”','opal 的词源追溯到 Sanskrit upala“宝石”。',1,'word-formation')]);
P('opaque','Opaque comes through French from Latin opacus, “shady or dark”; it can mean not letting light pass through or difficult to understand.',[C('opaque.s1','不透明的','The technician replaced the opaque window panel because staff could not see the warning light behind it.','工作人员看不到后面的警示灯，因此技术员更换了不透明的窗板。','The technician replaced the opaque window panel / because staff could not see / the warning light behind it.','opaque 可描述不透光、看不见背后物体的材料。','窗板挡住了警示灯。'),C('opaque.s2','晦涩难懂的','The contract’s opaque wording left the ferry operator unsure whether the discount applied after June.','合同中晦涩的措辞让渡船运营者不确定折扣是否在六月之后仍适用。','The contract’s opaque wording / left the ferry operator unsure / whether the discount applied after June.','opaque 也可比喻指含义不清、难以理解的表达。','运营者无法确定条款适用时间。')],M('The opaque glass let every ray of light through and made the warning lamp perfectly visible.','The opaque glass blocked light, so the warning lamp behind it could not be seen.','完全透光且清晰可见的玻璃不是 opaque。','meaning'),[q('Why was the window panel replaced?','staff could not see the warning light','the panel was an oncoming truck','the warning light was on the stage','不透明窗板挡住了警示灯。'),q('What did the operator find hard to understand?','the contract’s wording','the lamp’s color','the opal’s surface','opaque wording 表示条款晦涩难懂。',2,'context'),q('Which material is opaque?','a solid panel that blocks light','clear glass that lets people see through','a thin transparent film','opaque 描述不透光的材料。',1,'meaning'),q('Which phrase uses opaque figuratively?','an opaque explanation of the fee','an opaque window in the hall','an opaque curtain blocking light','说明难懂是比喻用法。',2,'distinction')]);
P('open','Open comes from Old English open; it can describe something not shut, available to the public, frank or undecided, or the actions of opening or beginning.',[C('open.s1','开着的；未关的','The harbor gate was open, so the rescue boat could pass through without waiting for a guard.','港口大门开着，因此救援船无需等待守卫就能通过。','The harbor gate was open / so the rescue boat could pass through / without waiting for a guard.','open 作形容词可表示门或盖子没有关上。','门处于打开状态，船可以通过。'),C('open.s2','营业的；开放的','The clinic is open to the public until eight, and walk-in patients do not need an appointment.','诊所向公众开放至八点，临时就诊者无需预约。','The clinic is open to the public until eight / and walk-in patients / do not need an appointment.','open 可表示营业中或允许公众使用。','诊所仍接待临时就诊者。'),C('open.s3','坦率的；未决定的','Nora was open about her concerns, but the committee left the final route decision open until morning.','诺拉坦率地表达了担忧，但委员会把最终路线决定留到早晨再定。','Nora was open about her concerns / but the committee left the final route decision open / until morning.','open 可表示坦率，也可表示问题尚未决定。','句中展示坦率表达和未定决定两种用法。'),C('open.s4','打开；开启','Please open the sample jar only after putting on protective gloves.','请先戴好防护手套，再打开样品罐。','Please open the sample jar / only after putting on protective gloves.','open 作动词可表示打开门、容器或盖子。','打开样品罐前须戴手套。'),C('open.s5','开始；开业','The harbor café will open at six, just in time for the first ferry passengers.','港口咖啡馆将在六点开门，正好赶上第一班渡船乘客。','The harbor café will open at six / just in time / for the first ferry passengers.','open 作动词也可表示开始营业或活动开始。','咖啡馆六点开业。')],M('The harbor gate was open because it was locked shut and the rescue boat could not pass through.','The harbor gate was open, allowing the rescue boat to pass through.','锁着且不能通行的门不是 open。','meaning'),[q('What allowed the rescue boat to pass?','the harbor gate was not shut','the clinic was open to patients','the café would open at six','open gate 表示门未关上。'),q('Until what time did the clinic welcome patients?','eight','six','midnight','诊所向公众开放到八点。',2,'context'),q('What did the committee leave undecided?','the final route','the clinic’s opening hours','whether the gate was shut','leave a decision open 表示暂未决定。',3,'meaning'),q('What should visitors do before they open the sample jar?','put on protective gloves','wait for the café to open','move the harbor gate','动词 open 指打开样品罐，先要戴手套。',4,'meaning')]);
P('open-air','Open-air combines open and air and describes an activity or place outside rather than inside a building.',C('open-air.s1','户外的；露天的','The village held an open-air concert beside the harbor, with the audience seated on blankets.','村庄在港口旁举办露天音乐会，观众坐在毯子上欣赏。','The village held an open-air concert / beside the harbor / with the audience seated on blankets.','open-air 作形容词表示在室外进行、没有屋顶遮蔽。','观众在港口边的户外听音乐会。'),M('The open-air concert was held inside a sealed basement with no access to outside air.','The open-air concert was held outside beside the harbor.','密闭地下室属于室内，不能称为 open-air。','meaning'),[q('Where was the concert held?','outside beside the harbor','inside a sealed basement','on a one-way ferry ticket','演出在港口旁户外举行。'),q('Which event is open-air?','a film screening in a park under the sky','a concert in a sealed underground room','a radio program recorded in a studio','open-air 指在室外进行。',1,'meaning'),q('Where did the audience sit?','on blankets','onstage behind the curtain','inside the rescue boat','观众坐在毯子上。',1,'context'),q('What does open-air describe in the phrase?','an outdoor setting','a sealed building','an online connection','open-air 表示露天或户外的。',1,'meaning')]);
P('open-book','Open-book combines open and book and describes an exam in which students may consult books or other texts.',C('open-book.s1','开卷的','The professor announced an open-book exam, so students could consult their printed notes during the test.','教授宣布考试可以开卷，学生答题时可以查阅打印笔记。','The professor announced an open-book exam / so students could consult / their printed notes during the test.','open-book exam 允许考生在考试中查阅资料。','学生可以查看笔记。'),M('The professor called it an open-book exam but expelled students for consulting any book or note.','The professor called it an open-book exam and allowed students to consult their notes.','禁止查看书本或笔记与开卷考试的定义相反。','meaning'),[q('What could students consult during the exam?','printed notes','a closed harbor gate','a nurse’s private schedule','开卷考试允许查阅打印笔记。'),q('Which test is open-book?','an exam where reference books may be used','a test requiring every text to be put away','a race with an open starting gate','open-book 描述允许查阅资料的考试。',1,'meaning'),q('What did the professor announce?','students could use notes during the test','students must memorize every note','the test would take place onstage','考试规定可以查阅笔记。',1,'context'),q('How is open-book formed?','open + book','open + air','on + book','open-book 由 open 和 book 组成。',1,'word-formation')]);
P('open-ended','Open-ended combines open and ended and describes a question without a fixed yes-or-no answer, or something without a set closing date.',[C('open-ended.s1','无固定答案的；无截止日的','The interviewer asked an open-ended question about how the new harbor plan might affect local fishers.','采访者提出了一个没有固定答案的问题，询问新的港口计划可能如何影响当地渔民。','The interviewer asked an open-ended question / about how the new harbor plan might affect / local fishers.','open-ended 问题允许受访者展开回答，而非只答是或否。','how 引导的问题需说明、解释。'),C('open-ended.s1','没有截止日期的','The museum’s call for volunteer guides is open-ended, so applications will remain available throughout the year.','博物馆招募志愿导览员没有固定截止日期，因此全年都可申请。','The museum’s call for volunteer guides is open-ended / so applications will remain available / throughout the year.','open-ended 也可指没有预设结束时间或截止日期。','全年持续接收申请。')],M('The interviewer asked an open-ended question that could be answered only with “yes” or “no.”','The interviewer asked an open-ended question inviting a detailed explanation.','只能回答 yes/no 的问题不是开放式问题。','meaning'),[q('What did the interviewer ask about?','the plan’s effect on local fishers','whether the café would open at six only','the color of the opaque window','问题关注港口计划对渔民的影响。'),q('How long can people apply to guide at the museum?','throughout the year','only until tomorrow morning','only during one open-air concert','open-ended 表示没有固定截止日，全年可申请。',1,'context'),q('Which is an open-ended question?','How did the new route change your work?','Did the route open? Answer yes or no.','Is the ticket one-way?','how 问题允许受访者详细展开。',1,'meaning'),q('Which meaning of open-ended fits an application period?','no fixed closing date','a question with only two answers','an exam where books are allowed','申请全年有效表示没有固定截止日。',1,'distinction')]);
P('open-minded','Open-minded combines open and minded and describes someone willing to consider new or different ideas.',C('open-minded.s1','思想开放的','The open-minded council listened to residents who proposed converting the empty station into a community workshop.','思想开放的市议会听取了居民的建议，他们想把空车站改成社区工坊。','The open-minded council listened to residents / who proposed converting the empty station / into a community workshop.','open-minded 描述愿意考虑新观点或不同意见。','议会认真听取了居民的新提议。'),M('The council was open-minded because it rejected every proposal before hearing what residents had to say.','The council was open-minded because it considered residents’ proposal before deciding.','不听意见就否决所有方案，体现拒绝新观点而非开放。','meaning'),[q('What did residents propose?','turning the empty station into a workshop','closing the harbor clinic','building an opaque wall around the council','居民建议把空车站改为社区工坊。'),q('Who is open-minded?','a person willing to consider unfamiliar ideas','a person who rejects all suggestions unheard','a person who never changes a route','open-minded 指愿意考虑新观点。',1,'meaning'),q('What did the council do?','listened to residents’ proposal','closed the meeting before they spoke','built the workshop without consulting anyone','议会听取了居民的提议。',1,'context'),q('Which word part suggests willingness to consider?','minded','air','-ward','open-minded 描写思想上愿意接受不同意见。',1,'meaning')]);
P('opener','Opener comes from open plus -er and can mean a tool for opening something or the first remark, act, or performance.',[C('opener.s1','开瓶器；开启工具','He used a bottle opener to remove the metal cap from the lemonade before the picnic.','野餐前，他用开瓶器取下柠檬汽水瓶上的金属盖。','He used a bottle opener / to remove the metal cap / from the lemonade before the picnic.','opener 可指用于打开瓶盖或容器的工具。','工具把金属瓶盖打开。'),C('opener.s1','开场表演；开场话','The band’s acoustic opener warmed up the audience before the main act took the stage.','乐队的原声开场表演让观众热身，随后主节目登台。','The band’s acoustic opener warmed up the audience / before the main act / took the stage.','opener 也可指演出或活动的开场节目或开场发言。','开场表演在主节目之前。')],M('He opened the lemonade bottle with a bottle opener by tightening the cap more firmly onto the neck.','He opened the lemonade bottle with a bottle opener by lifting off the metal cap.','拧紧瓶盖不会打开瓶子， opener 应用于取下瓶盖。','meaning'),[q('What did the bottle opener remove?','the metal cap','the main act’s microphone','the onshore data center','开瓶器取下了金属瓶盖。'),q('What warmed up the audience?','the band’s acoustic opener','the bottle cap','the main act’s final song','开场表演让观众进入状态。',1,'context'),q('Which object is an opener in the tool sense?','a corkscrew used to open a bottle','a concert’s first song','a short welcome speech','开瓶用的螺旋开塞器是开启工具。',1,'meaning'),q('Which use names the first performance of an event?','The local band was the opener for the festival.','She borrowed an opener from the kitchen.','He removed the cap with an opener.','第一句中 opener 指音乐节开场乐队。',1,'meaning')]);
P('opening','Opening comes from open plus -ing and can mean a beginning, a job or chance available, or a hole or space.',[C('opening.s1','开端；开场','The opening of the lecture introduced the history of Ontario before turning to the lake’s ecology.','讲座开场介绍了安大略的历史，随后转向湖泊生态。','The opening of the lecture introduced the history of Ontario / before turning / to the lake’s ecology.','opening 可指活动或作品的开始部分。','开场内容先介绍历史，再转到生态。'),C('opening.s2','空缺；机会','A seasonal opening at the observatory became available when the assistant moved to another province.','助理搬到另一个省后，天文台出现了一个季节性职位空缺。','A seasonal opening at the observatory / became available / when the assistant moved to another province.','opening 也指可申请的职位或机会。','原助理离开后出现岗位空缺。'),C('opening.s3','洞口；开口','A narrow opening in the stone wall let fresh air reach the storage room.','石墙上的一个狭窄开口让新鲜空气进入储藏室。','A narrow opening in the stone wall / let fresh air reach / the storage room.','opening 还可指物体上的洞口或可通过的空间。','空气通过墙上的开口流入。')],M('The observatory filled its seasonal opening even though no job or opportunity had become available.','The observatory advertised its seasonal opening after the assistant left.','没有职位空缺就无法招聘填补 seasonal opening。','meaning'),[q('What did the lecture’s opening introduce?','Ontario’s history','a job at the observatory','a hole in a stone wall','开场部分介绍了安大略历史。'),q('What became available at the observatory?','a seasonal job','a narrow wall opening','a ferry ticket','助理离开后出现季节性职位空缺。',2,'context'),q('What let fresh air into the storage room?','a narrow opening in the wall','the lecture’s opening paragraph','a seasonal employment notice','石墙开口让新鲜空气进入。',3,'meaning'),q('Which sentence uses opening to mean the beginning?','The opening of the film introduces the main character.','There is an opening for a nurse at the clinic.','Air passed through an opening in the wall.','第一句中的 opening 指电影开头。',1,'meaning')]);
P('openly','Openly is formed from open plus -ly and means in public or in a frank, unhidden way.',C('openly.s1','公然；坦白地','The mayor spoke openly about the town’s water shortage and answered residents’ questions without avoiding the problem.','市长坦率地谈到镇上的缺水问题，并直接回答居民提问。','The mayor spoke openly about the town’s water shortage / and answered residents’ questions / without avoiding the problem.','openly 作副词表示公开或坦率地表达。','市长没有回避缺水问题。'),M('The mayor spoke openly about the shortage by refusing to mention it in public or answer any questions.','The mayor spoke openly about the shortage by discussing it in public and answering questions.','拒绝公开提及与 openly 的“公然、坦白”含义相反。','meaning'),[q('What did the mayor discuss openly?','the town’s water shortage','the opal’s color only','the concert’s opening song','市长公开谈到镇上的缺水问题。'),q('Which action is done openly?','raising a concern in public and explaining it frankly','hiding the problem from everyone','leaving the meeting without speaking','openly 表示公开或坦率地表达。',1,'meaning'),q('How did the mayor respond to residents?','answered their questions directly','avoided the topic entirely','sent them a one-way ticket','他直接回答了居民的问题。',1,'context'),q('What is the base adjective in openly?','open','opening','opener','openly 由形容词 open 加 -ly 构成。',1,'word-formation')]);
P('openwork','Openwork combines open and work; it names decorative material or design made with deliberate holes or open patterns.',C('openwork.s1','镂空装饰；透孔织物','The museum displayed a silver bowl whose openwork sides formed a pattern of small leaves.','博物馆展出一只银碗，镂空的侧面组成了细小叶片的图案。','The museum displayed a silver bowl / whose openwork sides / formed a pattern of small leaves.','openwork 指以镂空孔洞构成的装饰性图案或制品。','叶片图案由碗侧面的镂空结构形成。'),M('The silversmith made the bowl solid and unbroken, then called its completely filled sides openwork.','The silversmith pierced the bowl’s sides with a leaf pattern to create openwork.','openwork 必须有开放孔洞或镂空图案，实心未开孔的侧面不符合定义。','meaning'),[q('What pattern appeared on the bowl?','small leaves formed by openwork','a list of telephone operators','a map of opposing armies','镂空部分组成细小叶片图案。'),q('What makes the bowl’s sides openwork?','they contain deliberate decorative openings','they are covered by an unbroken solid sheet','they are painted with an ordinary label','镂空孔洞构成装饰图案，符合 openwork。',1,'context'),q('Which object could accurately be described as openwork?','a lace panel with repeated holes','a plain solid metal plate','a closed wooden box with no pattern','透孔蕾丝具有开放的装饰孔洞。',1,'meaning'),q('In this entry, openwork refers mainly to?','a decorative open pattern in material','the act of operating a machine','a person’s private opinion','词条释义指镂空材料或图案。',1,'meaning')]);
P('opera','Opera came through Italian opera from Latin opera, “work”; it names a sung dramatic work or the art form.',[C('opera.s1','歌剧（一部）','The school choir performed an opera in which two singers acted out the story with a small orchestra.','学校合唱团演出了一部歌剧，两名歌手在小型管弦乐队伴奏下表演故事。','The school choir performed an opera / in which two singers acted out the story / with a small orchestra.','opera 可数时指一部由歌者表演、配有音乐的戏剧作品。','一部具体作品由歌手和乐队演绎。'),C('opera.s2','歌剧艺术','Although she rarely attends the theatre, she has studied opera as a musical art for years.','虽然她很少去剧院，但多年来一直把歌剧作为一种音乐艺术来研究。','Although she rarely attends the theatre / she has studied opera / as a musical art for years.','opera 不可数时可指歌剧这种艺术形式。','as a musical art 表明这里谈的是艺术类别。')],M('The singer performed three opera at the festival and then said she had never studied opera as an art.','The singer performed three operas at the festival and then said she had studied opera as an art.','表示三部具体作品时 opera 要用复数 operas；不可数的 opera 可指歌剧艺术。','plural'),[q('What did the choir perform?','a sung drama with singers and an orchestra','a lecture on how to operate a camera','a silent sculpture with no music','这是一部由歌手和乐队演出的戏剧作品。'),q('In which context does opera name an art form?','She has studied opera as a musical art.','The company staged an opera about a sailor.','Two singers performed one opera.','as a musical art 表示歌剧艺术这一类别。',2,'context'),q('Which sentence uses opera as a countable work?','The theatre staged two operas this month.','She has loved opera since childhood.','Opera is a musical art form.','two operas 指两部具体作品。',1,'grammar'),q('What is central to an opera in the source sense?','a story performed through singing and music','a machine controlled by an operator','a legal rule that becomes operative','歌剧以歌唱和音乐呈现戏剧故事。',1,'meaning')]);
P('operant','Operant was formed from operate with -ant; the adjective is associated with behaviour shaped by its consequences.',[C('operant.s1','操作性的','The psychologist used an operant task in which a rat learned to press a lever for food.','心理学家设计了一项操作性任务，让老鼠学会按压杠杆以获得食物。','The psychologist used an operant task / in which a rat learned / to press a lever for food.','operant 在心理学中形容会受行为后果塑造的行为或条件作用。','按压杠杆获得食物展示了行为和结果之间的联系。'),C('operant.s2','起作用的事物','The analyst identified trust as the key operant in the negotiation, because every decision depended on it.','分析师认为信任是谈判中的关键作用因素，因为每项决定都取决于它。','The analyst identified trust / as the key operant in the negotiation / because every decision depended on it.','operant 也可作名词，指起作用的人或事物。','trust 是影响全部决定的关键因素。')],M('The rat learned to press the lever for food, but the psychologist called the procedure operant conditioning shaped only by an unrelated reflex.','The rat learned to press the lever for food through operant conditioning shaped by the consequence.','操作性条件作用强调行为受其结果影响；无关反射并非例句描述的机制。','distinction'),[q('What did the rat learn to do for food?','press a lever','connect telephone calls','perform a sung drama','老鼠学会按杠杆来获得食物。'),q('What did the analyst call the key operant?','trust in the negotiation','the lever in the animal task','a branch of eye medicine','trust 是谈判中起关键作用的因素。',2,'context'),q('Which example uses the adjective operant in psychology?','operant conditioning shaped by rewards','an operant connecting phone calls','an opera sung by two actors','第一项描述行为受后果塑造的心理学概念。',1,'meaning'),q('In the second sense, an operant is?','a person or thing that produces an effect','a person who refuses every proposal','a drug made from opium','第二义项指起作用的人或事物。',2,'meaning')]);
P('operate','Operate came through Old French from Latin operari, “to work”; senses include function, control a machine, run a service, and perform surgery.',[C('operate.s1','运转；工作','The backup generator will operate automatically if the main power supply fails.','如果主电源断开，备用发电机就会自动运转。','The backup generator will operate automatically / if the main power supply / fails.','operate 可不及物，表示机器或系统运转。','发电机自动工作，不带直接宾语。'),C('operate.s2','操作；操纵','Only trained staff may operate the high-pressure valve in the laboratory.','只有受过培训的员工才可以操作实验室的高压阀。','Only trained staff may operate / the high-pressure valve / in the laboratory.','operate 可及物，表示操作机器或设备。','valve 是 operate 的直接宾语。'),C('operate.s3','经营；运营','A family company operates three ferry routes between the islands.','一家家族公司运营岛屿之间的三条渡轮航线。','A family company operates / three ferry routes / between the islands.','operate 也可表示经营企业、服务或线路。','公司负责运营三条航线。'),C('operate.s4','动手术','The surgeon will operate on the patient’s shoulder early tomorrow morning.','外科医生明天一早将为患者的肩部动手术。','The surgeon will operate on the patient’s shoulder / early tomorrow morning.','医学义通常用 operate on + 身体部位或患者。','operate on the shoulder 是动手术的结构。')],M('The surgeon operated the patient’s shoulder yesterday, although the team did not perform any surgery.','The surgeon operated on the patient’s shoulder yesterday.','表示为患者动手术时用 operate on，不能把身体部位直接作宾语。','grammar'),[q('What will the generator do if the power fails?','work automatically','run three ferry routes','receive shoulder surgery','备用发电机将自动运转。'),q('Who operates the ferry routes?','a family company','the laboratory valve','the patient’s surgeon','家族公司经营这三条航线。',3,'context'),q('Which sentence correctly describes surgery?','The surgeon operated on her shoulder.','The surgeon operated her shoulder.','The surgeon operated to the ferry route.','operate 表示动手术时应接 on。',4,'grammar'),q('Which use means “control a piece of equipment”?','operate the high-pressure valve','operate on the patient’s shoulder','operate three ferry routes','阀门是被操作的设备，属于设备义。',2,'meaning')]);
P('operating','Operating is the -ing form of operate; as a noun here it refers to the act or process of functioning.',C('operating.s1','运转；操作','Operating the old pump became noisy after sand entered its motor.','沙子进入电机后，这台旧水泵的运转变得很吵。','Operating the old pump / became noisy / after sand entered its motor.','operating 在此作名词，表示机器工作的过程。','the operating of the pump 指水泵运转这一过程。'),M('Operating the pump remained silent and noiseless even after sand made its motor rattle loudly.','Operating the pump became noisy after sand made its motor rattle.','operating 指机器运行过程；例句把它说成始终无声，却又说电机发出响声，前后矛盾。','meaning'),[q('What made the pump’s operating noisy?','sand entered its motor','the operator changed the opera score','a phone call reached the hospital','沙子进入电机后水泵运转变吵。'),q('What does operating name in the example?','the process of the pump working','the person who sells the pump','a medical operation on a shoulder','这里 operating 是机器运转的过程。',1,'meaning'),q('Which phrase uses operating as a noun for functioning?','the operating of the ventilation system','the operator of the ventilation system','the operation on the patient','第一项表示通风系统运行这一过程。',1,'grammar'),q('What was the pump like before sand entered the motor?','it was an old pump','it was a new opera house','it was a phone operator','例句明确说明这是台旧水泵。',1,'context')]);
P('operation','Operation comes through French from Latin operatio, “a working”; it names a medical procedure, a process, or a planned mission.',[C('operation.s1','手术','After reviewing the scan, the surgeon scheduled an operation to repair the athlete’s damaged tendon.','查看扫描结果后，外科医生安排了一次手术来修复运动员受损的肌腱。','After reviewing the scan / the surgeon scheduled an operation / to repair the athlete’s damaged tendon.','operation 可指为治疗伤病实施的医疗手术。','修复受损肌腱是医疗目的。'),C('operation.s2','经营；运作','The daily operation of the water plant depends on sensors that monitor pressure and flow.','水厂的日常运作依靠监测压力和流量的传感器。','The daily operation of the water plant / depends on sensors / that monitor pressure and flow.','operation 也指企业、设施或机器的运作过程。','传感器监测水厂日常运行。'),C('operation.s3','军事行动','The rescue operation continued through the night as crews searched the flooded valley.','救援队搜寻被洪水淹没的山谷，救援行动持续了一整夜。','The rescue operation continued through the night / as crews searched / the flooded valley.','operation 还可指有计划的军事、警务或救援行动。','多支队伍执行计划性搜索救援。')],M('The plant’s operation depended on sensors, so the surgeon scheduled an operation to repair a broken valve in the factory.','The plant’s operation depended on sensors, while the surgeon scheduled an operation to repair the athlete’s tendon.','手术义针对患者身体；工厂阀门维修不是 surgeon 实施的手术。','distinction'),[q('Why was the athlete’s operation scheduled?','to repair a damaged tendon','to monitor the plant’s water pressure','to search a flooded valley','手术用于修复运动员受损肌腱。'),q('What do the sensors support?','the daily running of the water plant','the rescue crews searching the valley','the surgeon repairing a tendon','传感器监测压力与流量，支撑水厂运作。',2,'context'),q('Which phrase means a planned rescue mission?','a rescue operation','a tendon operation','the daily operation of a plant','救援行动是计划执行的任务。',3,'meaning'),q('In “an operation to repair the tendon,” operation means?','a medical procedure','a company’s daily management','a search-and-rescue mission','修复肌腱指医疗手术。',1,'meaning')]);
P('operational','Operational combines operation with -al; it means ready to function or related to the practical running of work.',[C('operational.s1','投入运作的，可使用的','The control room confirmed that the flood-warning siren was operational before the storm arrived.','洪水预警警报器在暴风雨来临前被确认可以正常使用。','The control room confirmed / that the flood-warning siren was operational / before the storm arrived.','operational 可表示设备已准备好并能够正常工作。','警报器在风暴前可以使用。'),C('operational.s2','操作上的，业务的','The report separates operational costs, such as fuel and repairs, from the company’s loan payments.','报告将燃料、维修等运营成本与公司的贷款还款分开。','The report separates operational costs / such as fuel and repairs / from the company’s loan payments.','operational 也可表示与日常实际运作有关的。','燃料和维修是业务运行成本。')],M('The siren was operational, so it could not sound even though the control room had confirmed that it was ready to function.','The siren was operational and could sound when the storm warning was issued.','ready to function 与无法发声互相矛盾。','meaning'),[q('What could the flood-warning siren do?','function before the storm','separate the company’s loan payments','perform an eye examination','operational 表示警报器能正常工作。'),q('Which costs were operational in the report?','fuel and repairs','the company’s loan payments only','the storm’s rainfall totals','燃料和维修属于日常运营开支。',2,'context'),q('Which sentence uses operational to mean “ready to work”?','The backup siren is operational.','The report lists operational costs.','The committee debated an operation.','第一句描述设备可正常运行。',1,'meaning'),q('What does operational mean in “operational costs”?','connected with the practical running of a business','already broken and unusable','a person who connects telephone calls','这里指与日常业务运行有关。',2,'meaning')]);
P('operative','Operative comes from Latin operativus, “active or effective”; it can mean in force, crucial, or a worker or agent.',[C('operative.s1','有效的；实施中的','The revised safety rule becomes operative on 1 July, after every department receives the new instructions.','修订后的安全规定将于7月1日生效，届时各部门都已收到新指示。','The revised safety rule becomes operative / on 1 July / after every department receives the new instructions.','operative 可表示规则或安排已经生效、正在实施。','规定有明确的生效日期。'),C('operative.s2','关键的；最有意义的','In the editor’s correction, the operative word was “may,” which made the permission optional rather than compulsory.','在编辑的修订中，关键词是“可以”，它使许可成为可选而非强制。','In the editor’s correction / the operative word was “may” / which made the permission optional rather than compulsory.','the operative word 指决定话语含义的关键词。','may 改变了许可的强制程度。'),C('operative.s3','技工；工作人员；特工','A factory operative noticed the loose guard and stopped the packaging line before anyone was hurt.','一名工厂操作工发现防护罩松动，在有人受伤前停下了包装线。','A factory operative noticed the loose guard / and stopped the packaging line / before anyone was hurt.','operative 可作名词，指工人或执行任务的人员。','工厂员工发现危险并采取行动。')],M('The safety rule became operative on 1 July, but the manager said it would not be in force until the following year.','The safety rule became operative on 1 July and was in force from that date.','operative 表示已生效，不能同时说规则尚未生效。','meaning'),[q('When does the revised rule take effect?','on 1 July','after the factory line is replaced','only when the editor resigns','规定从7月1日起生效。'),q('Which word made the permission optional?','may','operative','compulsory','may 是决定许可含义的关键词。',2,'context'),q('Who stopped the packaging line?','a factory operative','the newspaper editor','the rule’s operative date','factory operative 指工厂工作人员。',3,'context'),q('Which sentence uses operative to mean “in force”?','The new regulation is operative today.','The operative word is “optional.”','A factory operative found the loose guard.','第一句中 operative 描述规定已经生效。',1,'meaning')]);
P('operator','Operator was formed from operate with the agent suffix -or; it can name a machine user, a service company, or a telephone worker.',[C('operator.s1','操作员','The crane operator checked the load chart before lifting the steel beam above the road.','起重机操作员在把钢梁吊到道路上方前查看了载荷表。','The crane operator checked the load chart / before lifting the steel beam / above the road.','operator 可指操作机器或设备的人。','此人负责操纵起重机。'),C('operator.s2','运营商，经营者','The island’s ferry operator added an evening sailing after residents complained about the timetable.','居民抱怨时刻表后，岛上的渡轮运营商增加了一班晚间航次。','The island’s ferry operator added an evening sailing / after residents complained / about the timetable.','operator 也可指运营某项服务或业务的公司。','渡轮公司负责安排航班。'),C('operator.s3','接线员','The caller asked the telephone operator to connect her to the hospital’s maternity ward.','来电者请电话接线员为她转接医院产科病房。','The caller asked the telephone operator / to connect her / to the hospital’s maternity ward.','operator 还可指负责接通电话的接线员。','接线员负责转接来电。')],M('The crane operator ran the ferry company’s timetable and connected the caller to the maternity ward while standing nowhere near a crane.','The crane operator lifted the beam, the ferry operator set the timetable, and the telephone operator connected the caller.','三个语境各有不同职责，不能把操作员、运营公司和电话接线员混为一谈。','distinction'),[q('Who checked the load chart?','the crane operator','the ferry operator','the telephone operator','查看吊装载荷表的是起重机操作员。'),q('What did the ferry operator add?','an evening sailing','a crane load chart','a hospital telephone extension','渡轮运营商增加了晚间航次。',2,'context'),q('Which operator connects a caller to a hospital ward?','the telephone operator','the crane operator','the ferry operator','接线员负责转接电话。',3,'context'),q('Which example uses operator for a company?','The ferry operator changed its timetable.','The operator lifted the steel beam.','The operator connected the call.','渡轮公司运营服务，因此是公司义。',2,'meaning')]);
P('ophthalmology','Ophthalmology combines Greek ophthalmos, “eye,” with -logia, “study”; it is the medical specialty of the eyes.',C('ophthalmology.s1','眼科学','The patient was referred to ophthalmology after an eye specialist detected a pressure problem.','眼科专家发现眼压问题后，患者被转诊到眼科学科就诊。','The patient was referred to ophthalmology / after an eye specialist detected / a pressure problem.','ophthalmology 指研究和治疗眼睛及眼病的医学领域。','眼压问题由眼科专科处理。'),M('The patient was referred to ophthalmology for a broken ankle, although no eye examination or eye problem was involved.','The patient was referred to ophthalmology for the pressure problem in the eye.','眼科学专门研究和治疗眼睛，脚踝骨折不属于其范围。','distinction'),[q('Why was the patient referred to ophthalmology?','an eye-pressure problem was detected','the patient needed a ferry timetable','the patient had a damaged tendon','转诊原因是眼压问题。'),q('What field does ophthalmology study and treat?','the eyes and their diseases','the operation of ferry routes','the behavior of telephone callers','ophthalmology 是眼睛及眼病的医学领域。',1,'meaning'),q('Which specialist works in ophthalmology?','an eye doctor','a crane operator','an opera singer','眼科医生在眼科学领域工作。',1,'context'),q('Which Greek element in ophthalmology means “eye”?','ophthalmos','-logia','operari','ophthalmos 的意思是眼睛。',1,'word-formation')]);
P('opiate','Opiate came from opium, ultimately from Greek opion, “poppy juice”; it names an opium-derived drug and figuratively a soothing influence.',[C('opiate.s1','鸦片剂；安眠药','The doctor warned that the prescribed opiate could cause drowsiness and told the patient not to drive after taking it.','医生提醒患者，处方鸦片类药物可能导致嗜睡，服药后不要开车。','The doctor warned / that the prescribed opiate could cause drowsiness / and told the patient not to drive after taking it.','opiate 可指从鸦片制成或与之相关的药物，也可比喻使人麻痹或安慰的事物。','药物可能使患者嗜睡，体现药物义。'),C('opiate.s1','鸦片剂；安眠药','The essay called the endless entertainment an opiate that distracted the public from difficult questions.','文章把无休止的娱乐称为一种麻醉剂，使公众分心而不去思考棘手问题。','The essay called the endless entertainment / an opiate / that distracted the public from difficult questions.','opiate 可比喻让人暂时忘却问题、获得安慰的事物。','娱乐被比喻为让公众分心的麻醉剂。')],M('The doctor warned that the opiate would sharpen alertness and prevent drowsiness, so the patient was told to take it before driving.','The doctor warned that the opiate could cause drowsiness and told the patient not to drive after taking it.','opiate 可能导致嗜睡；把它说成提高清醒度并建议服药后开车不安全且与义项相反。','meaning'),[q('What possible effect did the doctor mention?','drowsiness','a stronger eye-pressure reading','a change in the ferry timetable','医生提醒药物可能引起嗜睡。'),q('What did the essay call an opiate?','entertainment that distracted the public','a medical operation on the eye','a telephone worker','文章把让公众分心的娱乐作比喻。',1,'context'),q('Which sentence uses opiate figuratively?','The spectacle acted as an opiate for anxious viewers.','The patient received an opiate by prescription.','The crane operator checked the load.','第一句把安慰、麻痹人的事物比作 opiate。',1,'meaning'),q('What should the patient do with the prescribed opiate?','follow the doctor’s directions','take it before driving to stay alert','share it with anyone who feels tired','处方药必须按医嘱使用。',1,'context')]);
P('opinion','Opinion came through Old French from Latin opinionem, “belief or judgement”; it names a view, an evaluation, or expert advice.',[C('opinion.s1','意见；看法','In my opinion, the wetlands should remain protected even if the road project is delayed.','依我看，即使道路工程延期，也应该继续保护这些湿地。','In my opinion / the wetlands should remain protected / even if the road project is delayed.','opinion 可表示个人相信或判断的看法。','In my opinion 引出个人观点。'),C('opinion.s2','评价；印象','The reviewer has a high opinion of the orchestra because its performances are precise and expressive.','评论家对这支管弦乐团评价很高，因为他们的演出精准而富有表现力。','The reviewer has a high opinion of the orchestra / because its performances / are precise and expressive.','have a high/low opinion of 表示对某人或事物评价高低。','评价来自演出质量。'),C('opinion.s3','专家意见；鉴定','Before choosing a treatment, the family requested a second medical opinion from another specialist.','选择治疗方案前，家属请另一位专科医生再提供一份医疗意见。','Before choosing a treatment / the family requested a second medical opinion / from another specialist.','opinion 也可指专家针对具体问题给出的专业判断。','another specialist 提供第二份专业意见。')],M('According to my opinion, the reviewer has a high opinion of the orchestra but the family requested no medical opinion from a specialist.','In my opinion, the reviewer has a high opinion of the orchestra, and the family requested a second medical opinion.','表达个人看法通常说 in my opinion；题干后半句也与第二份专家意见的语境不符。','collocation'),[q('What does the speaker believe about the wetlands?','they should remain protected','they should be replaced by an opera house','they are already part of the orchestra','说话者认为湿地应继续受到保护。'),q('Why does the reviewer have a high opinion of the orchestra?','its performances are precise and expressive','it cancelled every performance','it provided a medical diagnosis','评论家的高评价来自精准且富有表现力的演出。',2,'context'),q('Who gives the second medical opinion?','another specialist','the orchestra’s conductor','the road contractor','第二份医疗意见由另一位专科医生给出。',3,'context'),q('Which phrase is standard for introducing a personal view?','in my opinion','according to my opinion','by my opinion','标准搭配是 in my opinion。',1,'collocation')]);
P('opinionated','Opinionated is formed from opinion with an adjective-forming ending; it describes someone who asserts views strongly and resists discussion.',C('opinionated.s1','武断的','The opinionated panelist dismissed every objection before the other speakers had finished.','这位固执己见的讨论嘉宾在其他发言者还没说完前，就驳回了每一条异议。','The opinionated panelist dismissed every objection / before the other speakers / had finished.','opinionated 常带贬义，指强硬表达观点且不愿听取不同看法。','不等别人说完便驳回异议体现了拒绝讨论。'),M('The opinionated chair patiently invited every challenge, reconsidered her views, and welcomed being persuaded.','The opinionated chair dismissed challenges and insisted that her own view could not be questioned.','乐于听取并改变看法与 opinionated 所描述的固执态度相反。','meaning'),[q('What did the panelist do before others finished?','dismissed their objections','asked the operator to connect a call','scheduled an operation','她在别人说完前就驳回了异议。'),q('What attitude does opinionated describe here?','strong views with little openness to challenge','a calm willingness to change one’s mind','professional knowledge of eye disease','强烈坚持观点且不愿听反对意见。',1,'meaning'),q('Who is best described as opinionated?','someone who rejects every objection without discussion','someone who asks others to explain their views','someone who has no stated preference','不讨论就拒绝所有异议的人符合释义。',1,'meaning'),q('Is opinionated usually approving here?','No; it is generally critical.','Yes; it always means fair and open-minded.','Yes; it means an expert gave a medical opinion.','词条说明该形容词通常带贬义。',1,'context')]);
P('opponent','Opponent comes from Latin opponentem, from opponere, “to set against”; it means an adversary in a contest or dispute.',C('opponent.s1','对手；对抗方','The chess opponent studied the board quietly before making a move that threatened the queen.','国际象棋对手安静地研究棋盘，然后走了一步威胁到皇后的棋。','The chess opponent studied the board / quietly before making a move / that threatened the queen.','opponent 指在比赛、争论或竞争中与你对抗的人。','对方棋手作出威胁皇后的棋步。'),M('The chess opponent was the player on her own team who helped her plan each move against the other player.','The chess opponent was the player across the board who competed against her.','帮自己计划棋步的队友是同伴，不是对手。','distinction'),[q('What did the chess opponent threaten?','the queen','the telephone operator','the flood-warning siren','对手走了一步威胁皇后的棋。'),q('Who is the opponent in the example?','the player competing across the board','the player’s teammate planning moves','the person repairing the chess clock','棋盘对面与其比赛的人是对手。',1,'context'),q('Which situation has an opponent?','two candidates debating against each other','a doctor examining her own eye','a machine running automatically','互相辩论的候选人彼此是对抗方。',1,'meaning'),q('Opponent most nearly means?','adversary','operator','opinion','opponent 指竞争或争论中的对手。',1,'meaning')]);
P('opportunist','Opportunist is formed from opportunity with -ist; it names someone who seizes chances for self-interest, often without principle.',C('opportunist.s1','投机者','The opportunist changed political sides after the poll showed which party was likely to win.','民调显示哪个政党可能获胜后，这名投机者便改变了政治立场。','The opportunist changed political sides / after the poll showed / which party was likely to win.','opportunist 常含贬义，指为私利抓住时机、缺少原则的人。','他依照胜选可能性改换立场。'),M('The principled negotiator kept the same position despite personal gain, so the report called her an opportunist.','The negotiator changed sides for personal gain, so the report called her an opportunist.','坚持原则且不因私利改立场，不足以称为 opportunist。','meaning'),[q('What prompted the politician to change sides?','the poll suggested which party might win','the eye specialist scheduled a checkup','the ferry route was temporarily closed','民调显示胜选可能性后他改变了立场。'),q('What quality makes the person an opportunist?','seizing chances for self-interest with little principle','holding a view firmly but welcoming debate','operating a machine safely','机会主义者为自身利益抓住时机且常不讲原则。',1,'meaning'),q('Which action best fits opportunist?','switching allegiance only when it brings a personal advantage','keeping a promise despite a cost','taking a fair opportunity while following agreed rules','只在能获利时改换阵营符合贬义用法。',1,'meaning'),q('Is opportunity itself necessarily negative?','No; the negative judgement belongs to opportunist.','Yes; opportunity always means dishonest gain.','No; opportunist means a neutral chance.','opportunity 是中性的机会，opportunist 才常带贬义。',1,'context')]);
P('opportunistic','Opportunistic is formed from opportunist with -ic; it can mean self-serving or, in medicine, occurring when defences are weak.',[C('opportunistic.s1','投机的','The company’s opportunistic bid came only after its rival had spent years developing the project.','竞争对手多年开发该项目后，这家公司才提出投机性的收购报价。','The company’s opportunistic bid came only after its rival / had spent years / developing the project.','opportunistic 可形容见机谋利、缺少长期计划或原则的做法。','公司趁对手投入多年后才出价，体现乘机获利。'),C('opportunistic.s2','机会性的（医学）','The infection was opportunistic, appearing after chemotherapy had weakened the patient’s immune system.','患者的免疫系统因化疗而减弱后，这种机会性感染才出现。','The infection was opportunistic / appearing after chemotherapy / had weakened the patient’s immune system.','医学上 opportunistic 可描述在人体防御能力低下时乘机感染的病原体或感染。','感染出现在免疫系统变弱之后。')],M('The infection was called opportunistic even though the patient’s immune defences were strong and the pathogen could not take advantage of weakness.','The infection was opportunistic because it appeared when treatment had weakened the patient’s immune defences.','医学义强调感染趁宿主防御力减弱时出现。','meaning'),[q('When did the company make its bid?','after its rival had invested years in the project','before the rival announced any project','after the company completed the project itself','公司在对手投入多年后才出价。'),q('What weakened the patient’s immune system?','chemotherapy','a ferry schedule change','a chess opponent’s move','化疗使患者免疫系统减弱。',2,'context'),q('Which sentence uses opportunistic in the medical sense?','An opportunistic infection appeared during immune suppression.','An opportunistic bidder waited for a rival to invest.','The operator started the machine at noon.','第一句是医学上的机会性感染。',2,'meaning'),q('In the business context, opportunistic most nearly means?','taking advantage of a chance for gain','ready and functioning','opposed to every possible proposal','公司趁对手投入后出价，属于见机谋利。',1,'meaning')]);
P('opportunity','Opportunity came through French from Latin opportunitas, “a favorable occasion”; it means a chance to act or a prospect for advancement.',[C('opportunity.s1','机会；时机','The internship offers an opportunity to learn how field researchers measure water quality.','这次实习提供了学习野外研究人员如何测量水质的机会。','The internship offers an opportunity / to learn how field researchers / measure water quality.','opportunity 常表示做某事的有利时机，后可接 to do。','实习让学生有机会学习测量方法。'),C('opportunity.s2','就业或发展的前途','The regional office offers more opportunities for engineers who want to move into management.','地区办事处为想转入管理岗位的工程师提供了更多发展机会。','The regional office offers more opportunities / for engineers / who want to move into management.','复数 opportunities 也可指就业或发展的前景。','工程师有机会进入管理岗位。')],M('The internship gave her an opportunity for learning how to measure water quality, despite no chance to learn anything.','The internship gave her an opportunity to learn how to measure water quality.','opportunity 可接 to do 表示做某事的机会；“给机会”与“没有学习机会”也不能并存。','grammar'),[q('What could the intern learn?','how researchers measure water quality','how to connect a hospital call','how to repair an opera costume','实习提供学习水质测量的机会。'),q('Who may find more career opportunities at the regional office?','engineers seeking management roles','patients receiving eye examinations','chess opponents changing sides','想进入管理岗位的工程师获得更多发展机会。',2,'context'),q('Which construction is standard?','an opportunity to apply','an opportunity for apply','an opportunity applying','opportunity 后可接 to do。',1,'grammar'),q('In “more opportunities for engineers,” opportunities means?','prospects for work or advancement','a single chance to perform a task','a medical operation','这里指职业或发展的前景。',2,'meaning')]);
P('oppose','Oppose comes from Latin opponere, “to set against”; it means resisting an idea or placing things in contrast.',[C('oppose.s1','反对；抵制','Many residents oppose the bypass because it would cut through the wetland used by migrating birds.','许多居民反对这条绕行公路，因为它会穿过候鸟使用的湿地。','Many residents oppose the bypass / because it would cut through / the wetland used by migrating birds.','oppose 可及物，表示反对并试图阻止某计划。','居民因道路会破坏湿地而反对计划。'),C('oppose.s2','与……对立；使对抗','The report opposes short-term savings to the long-term costs of repairing the damaged bridge.','报告将短期节省与修复受损桥梁的长期成本作对比。','The report opposes short-term savings / to the long-term costs / of repairing the damaged bridge.','oppose 也可表示把两种事物并列对照或置于对立面。','短期节省与长期维修成本形成对照。')],M('The residents opposed to the bypass the plan, while the report opposed short-term savings to long-term repair costs.','The residents opposed the bypass, while the report opposed short-term savings to long-term repair costs.','oppose 作主动及物动词时直接接宾语，不应再插入介词 to。','grammar'),[q('Why did residents oppose the bypass?','it would cut through a bird-using wetland','it would create an eye clinic','it would shorten the ferry route','居民反对道路，因为它会穿过候鸟湿地。'),q('What does the report oppose to short-term savings?','the long-term repair costs','the residents’ bird survey','the eye clinic’s appointment list','报告把短期节省与长期维修成本作对比。',2,'context'),q('Which sentence uses oppose to mean “resist a plan”?','Residents oppose the new road.','The report opposes savings to future costs.','The colors oppose each other in the chart.','第一句表示居民反对道路计划。',1,'meaning'),q('How is oppose used in “oppose a proposal”?','as a transitive verb directly before its object','with to before every direct object','only as a passive adjective','oppose 后直接接被反对的计划。',1,'grammar')]);
P('opposed','Opposed is the past participle of oppose and commonly functions as an adjective in opposed to, “against or in contrast with.”',C('opposed.s1','反对的','The residents are opposed to building the dam because it would flood several farms.','居民反对修建水坝，因为这会淹没好几处农场。','The residents are opposed to building the dam / because it would flood / several farms.','opposed 常作表语形容词，结构为 be opposed to + 名词或动名词。','building 是 opposed to 后的动名词。'),M('The residents are opposed to build the dam because it would flood several farms.','The residents are opposed to building the dam because it would flood several farms.','opposed to 中的 to 是介词，后接动名词而非不定式。','grammar'),[q('Why are residents opposed to the dam?','it would flood several farms','it would connect telephone calls','it would repair their harvest','水坝会淹没农场，所以居民反对它。'),q('What construction follows opposed to here?','a gerund phrase','a bare infinitive','a past-tense clause with no subject','opposed to 后接 building 这一动名词短语。',1,'grammar'),q('Which sentence correctly uses opposed?','The committee is opposed to cutting the wetland.','The committee is opposed to cut the wetland.','The committee opposed to the plan yesterday.','第一句符合 be opposed to + 动名词结构。',1,'grammar'),q('What does opposed to mean here?','against a proposed action','ready and functioning','a person who connects telephone calls','居民不赞成修建水坝。',1,'meaning')]);
P('opposing','Opposing is the -ing form of oppose used as an adjective; it describes positions, forces, or views that conflict.',C('opposing.s1','对立的；相反的','The two opposing teams entered the stadium from opposite gates before the final match.','决赛前，两支对立的球队从相反的入口进入体育场。','The two opposing teams entered the stadium / from opposite gates / before the final match.','opposing 可形容彼此竞争或相互冲突的双方。','两支队伍将在决赛中互相竞争。'),M('The opposing teams played on the same side and cooperated throughout the match without competing.','The opposing teams played against each other in the final match.','彼此合作且不竞争的队伍不是 opposing teams。','meaning'),[q('Where did the two teams enter?','from opposite gates','through one shared telephone line','from the same operating room','两队从相反的入口进入体育场。'),q('What does opposing describe in “opposing teams”?','teams competing against each other','teammates working toward the same side','operators running the same ferry company','opposing teams 是互相竞争的队伍。',1,'meaning'),q('Which phrase uses opposing as an adjective?','opposing views on the dam','opposed to building the dam','oppose the proposal','opposing 直接修饰 views。',1,'grammar'),q('What happened before the final match?','the rival teams entered the stadium','the teams agreed to cancel all competition','the surgeon performed an operation','比赛前两支对手球队进入体育场。',1,'context')]);
})();
